let alwaysClickableButtonFeedbackTimer = 0;
let alwaysClickableButtonFeedbackOwner = null;

function showAlwaysClickableButtonFeedback(
  message,
  owner = null
) {
  let feedback = document.getElementById(
    "rml-button-action-feedback"
  );
  if (!feedback) {
    feedback = document.createElement("div");
    feedback.id =
      "rml-button-action-feedback";
    feedback.setAttribute("role", "status");
    feedback.setAttribute(
      "aria-live",
      "polite"
    );
    document.body.appendChild(feedback);
  }
  feedback.textContent = String(
    message ||
      window.RMLI18n.t("ui.literal.fc8642a58ba7")
  );
  feedback.hidden = false;
  alwaysClickableButtonFeedbackOwner =
    owner;
  window.clearTimeout(
    alwaysClickableButtonFeedbackTimer
  );
  alwaysClickableButtonFeedbackTimer =
    window.setTimeout(() => {
      feedback.hidden = true;
      alwaysClickableButtonFeedbackOwner =
        null;
    }, 3600);
}

function setAlwaysClickableButtonAvailability(
  button,
  available,
  reason = ""
) {
  if (
    !button ||
    String(button.tagName || "") !==
      window.RMLI18n.t("ui.literal.170f32e23a92")
  ) {
    return;
  }
  const enabled = available === true;
  button.disabled = false;
  button.setAttribute(
    "aria-disabled",
    String(!enabled)
  );
  button.classList.toggle(
    "rml-action-unavailable",
    !enabled
  );
  if (!enabled) {
    button.dataset.unavailableReason =
      String(
        reason ||
          button.title ||
          window.RMLI18n.t("ui.literal.fc8642a58ba7")
      );
  } else {
    delete button.dataset.unavailableReason;
    if (
      alwaysClickableButtonFeedbackOwner ===
        button
    ) {
      const feedback =
        document.getElementById(
          "rml-button-action-feedback"
        );
      window.clearTimeout(
        alwaysClickableButtonFeedbackTimer
      );
      alwaysClickableButtonFeedbackTimer = 0;
      alwaysClickableButtonFeedbackOwner = null;
      if (feedback) {
        feedback.hidden = true;
      }
    }
  }
}

function setExportControlAvailability(
  button,
  available
) {
  if (
    !button ||
    String(button.tagName || "") !==
      window.RMLI18n.t("ui.literal.170f32e23a92")
  ) {
    return;
  }
  const enabled = available === true;
  button.disabled = !enabled;
  button.setAttribute(
    "aria-disabled",
    String(!enabled)
  );
  button.classList.toggle(
    "rml-action-unavailable",
    !enabled
  );
  delete button.dataset.unavailableReason;
}

function exportControlAvailable(button) {
  return Boolean(
    button &&
    button.disabled !== true &&
    button.getAttribute("aria-disabled") !==
      "true"
  );
}

Object.defineProperty(
  window,
  window.RMLI18n.t("ui.literal.93cccc415f4e"),
  {
    value: Object.freeze({
      set:
        setAlwaysClickableButtonAvailability
    }),
    writable: false,
    enumerable: true,
    configurable: true
  }
);

document.addEventListener(
  "click",
  event => {
    const button = event.target?.closest?.(
      'button[aria-disabled="true"]'
    );
    if (!button) return;
    if (button.id === "pack-into-node") {
      const bridge = window.RMLBuilderBridge;
      const graph =
        bridge?.getExtensionStateReference?.(
          "typedNodeGraph"
        );
      const nodeCount = Number(
        bridge?.getConfigurationNodeCount?.()
      );
      if (
        button.getAttribute("aria-busy") ===
          "true" ||
        graph?.active === true ||
        (
          Number.isFinite(nodeCount) &&
          nodeCount > 0
        )
      ) {
        setAlwaysClickableButtonAvailability(
          button,
          true
        );
        return;
      }
      if (
        !bridge ||
        !Number.isFinite(nodeCount) ||
        button.dataset.runtimeReadiness !==
          "ready"
      ) {
        return;
      }
    }
    event.preventDefault();
    event.stopImmediatePropagation();
    showAlwaysClickableButtonFeedback(
      button.dataset.unavailableReason ||
        button.title,
      button
    );
  },
  true
);

function removeLegacyHelpHashFromAddress() {
  if (!/^#(?:info-|shortcut-)/i.test(window.location.hash)) {
    return;
  }

  window.history.replaceState(
    window.history.state,
    "",
    `${window.location.pathname}${window.location.search}`
  );
}

