function outlineTypeFamilyForType(type) {
  return OUTLINE_PALETTE_TYPE_FAMILIES.find(family =>
    family.groupTypes.includes(type)
  ) || null;
}

function outlineFamilySymbolForType(type) {
  return outlineTypeFamilyForType(type)?.symbol ||
    TYPE_DEFINITIONS.find(item => item.type === type)?.badge ||
    type;
}

function outlineSymbolMarkup(symbol) {
  const iconIds = { "#": "icon-node-hash", "VEC": "icon-node-vec" };
  const iconId = iconIds[String(symbol || "")];
  if (!iconId) return escapeHtml(String(symbol || "?"));
  return `<svg class="rml-node-symbol-svg" viewBox="0 0 24 24" aria-hidden="true"><use href="assets/rml-icons.svg?v=1.21.20-universal-presentation-dev419-runtime-color-fidelity-overlay-open#${iconId}"></use></svg>`;
}

function outlinePaletteEntriesForGroup(group) {
  const definitions = TYPE_DEFINITIONS.filter(item => item.group === group);
  const byType = new Map(definitions.map(item => [item.type, item]));
  const consumed = new Set();
  const entries = [];

  for (const family of OUTLINE_PALETTE_TYPE_FAMILIES) {
    const variants = family.groupTypes.map(type => byType.get(type)).filter(Boolean);
    if (variants.length < 2) continue;
    variants.forEach(item => consumed.add(item.type));
    entries.push({ kind: "family", family, variants, item: variants[0] });
  }

  definitions.filter(item => !consumed.has(item.type))
    .forEach(item => entries.push({ kind: "single", item }));
  return entries;
}

