function generateProjectFile() {
  requireGeneratedGuidance();
  const settings = currentFlattenedNodes()
    .filter(entry => entry.node.kind === "setting");
  const graphContribution =
    getTypedNodeGraphContribution();
  const graphRequirements =
    graphContribution?.requirements || {};
  const usesElements =
    settings.some(entry =>
      [
        "colorX",
        "int2",
        "int3",
        "int4",
        "float2",
        "float3",
        "float4",
        "double2",
        "double3",
        "double4"
      ].includes(entry.node.valueType)
    ) ||
    graphRequirements.usesElements === true;
  const usesRenderiteShared =
    settings.some(
      entry => entry.node.valueType === "colorX"
    ) ||
    graphRequirements.usesRenderiteShared === true;
  const className = generatedBaseName();
  const namespaceName =
    state.metadata.namespaceName
      .split(".")
      .map(part => toPascalCase(part, window.RMLI18n.t("index.text.43c7d869d357")))
      .join(".") ||
    window.RMLI18n.t("ui.literal.d1751e2241e4");
  const resonitePath = escapeXml(
    normalizedResonitePath(
      state.exportOptions.resonitePath
    )
  );
  const versionMetadata =
    projectVersionMetadata();

  const referenceMap = new Map();

  const addReference = reference => {
    if (
      !reference ||
      typeof reference !== "object"
    ) {
      return;
    }

    const include = String(
      reference.include || ""
    ).trim();

    if (!include) {
      return;
    }

    referenceMap.set(
      include.toLowerCase(),
      {
        include,
        hintPath:
          String(
            reference.hintPath || ""
          ).trim(),
        private:
          reference.private === true
      }
    );
  };

  if (usesElements) {
    addReference({
      include: "Elements.Core",
      hintPath:
        "$(ResonitePath)Elements.Core.dll"
    });
  }

  if (usesRenderiteShared) {
    addReference({
      include: window.RMLI18n.t("ui.literal.38b9a2fd4ae5"),
      hintPath:
        "$(ResonitePath)Renderite.Shared.dll"
    });
  }

  for (
    const reference of
    Array.isArray(
      graphRequirements.references
    )
      ? graphRequirements.references
      : []
  ) {
    addReference(reference);
  }

  const optionalReferences =
    [...referenceMap.values()]
      .map(reference => {
        const include =
          escapeXml(reference.include);
        const hintPath =
          escapeXml(reference.hintPath);
        const privateValue =
          reference.private
            ? window.RMLI18n.t("ui.auto.2bafb66af5d9")
            : window.RMLI18n.t("ui.text.97cdbdc7feff");

        if (!hintPath) {
          return `    <Reference Include="${include}" />`;
        }

        return `    <Reference Include="${include}">
      <HintPath>${hintPath}</HintPath>
      <Private>${privateValue}</Private>
    </Reference>`;
      })
      .join("\n\n");

  const packageMap = new Map();

  for (
    const packageReference of
    Array.isArray(
      graphRequirements.packageReferences
    )
      ? graphRequirements.packageReferences
      : []
  ) {
    if (
      !packageReference ||
      typeof packageReference !== "object"
    ) {
      continue;
    }

    const include = String(
      packageReference.include || ""
    ).trim();
    const version = String(
      packageReference.version || ""
    ).trim();

    if (!include || !version) {
      continue;
    }

    packageMap.set(
      include.toLowerCase(),
      {
        include,
        version,
        privateAssets:
          String(
            packageReference.privateAssets || ""
          ).trim(),
        includeAssets:
          String(
            packageReference.includeAssets || ""
          ).trim()
      }
    );
  }

  const packageReferences =
    [...packageMap.values()]
      .map(packageReference => {
        const attributes = [
          `Include="${escapeXml(
            packageReference.include
          )}"`,
          `Version="${escapeXml(
            packageReference.version
          )}"`
        ];

        if (packageReference.privateAssets) {
          attributes.push(
            `PrivateAssets="${escapeXml(
              packageReference.privateAssets
            )}"`
          );
        }

        if (packageReference.includeAssets) {
          attributes.push(
            `IncludeAssets="${escapeXml(
              packageReference.includeAssets
            )}"`
          );
        }

        return `    <PackageReference ${attributes.join(
          " "
        )} />`;
      })
      .join("\n");

  const frameworkReferences =
    (Array.isArray(
      graphRequirements.frameworkReferences
    )
      ? graphRequirements.frameworkReferences
      : [])
      .map(value => String(value || "").trim())
      .filter(Boolean)
      .map(
        value =>
          `    <FrameworkReference Include="${escapeXml(
            value
          )}" />`
      )
      .join("\n");

  const allowUnsafeBlocks =
    graphRequirements.allowUnsafeBlocks === true;
  const useWindowsForms =
    graphRequirements.useWindowsForms === true;
  const targetFramework =
    useWindowsForms
      ? "net10.0-windows"
      : "net10.0";
  const projectGuidance =
    state.metadata.includeGuide === true
      ? window.RMLGuidance.text("configuration", "projectTarget")
      : "";

  return globalThis.RMLCodeTemplates.text("configuration", "source_009", [projectGuidance,
targetFramework,
allowUnsafeBlocks
      ? "\n    <AllowUnsafeBlocks>{{i18n:ui.text.5ffe533b830f}}</AllowUnsafeBlocks>"
      : "",
useWindowsForms
      ? "\n    <UseWindowsForms>{{i18n:ui.text.5ffe533b830f}}</UseWindowsForms>\n    <EnableWindowsTargeting>{{i18n:ui.text.5ffe533b830f}}</EnableWindowsTargeting>"
      : "",
escapeXml(className),
escapeXml(namespaceName),
escapeXml(versionMetadata.version),
escapeXml(versionMetadata.assemblyVersion),
escapeXml(versionMetadata.fileVersion),
escapeXml(versionMetadata.informationalVersion),
resonitePath,
optionalReferences
      ? `\n\n${optionalReferences}`
      : "",
packageReferences
    ? `\n\n  <ItemGroup>\n${packageReferences}\n  </ItemGroup>`
    : "",
frameworkReferences
    ? `\n\n  <ItemGroup>\n${frameworkReferences}\n  </ItemGroup>`
    : ""]);
}

