let projectDialogOpenSequence = 0;

async function openProjectDialog() {
  const sequence =
    ++projectDialogOpenSequence;
  setProjectFileStatus("");

  try {
    await ensureLazyStyleBundle("project");
  } catch (error) {
    console.error(window.RMLI18n.t("ui.literal.dabddb115368"), error);
    void showBuilderNotice({
      tone: "warning",
      kicker: window.RMLI18n.t("ui.auto.311bfc6f1013"),
      title: window.RMLI18n.t("ui.auto.75851b45d672"),
      message:
        error instanceof Error
          ? error.message
          : String(error),
      details:
        window.RMLI18n.t("ui.literal.b3e5fc4cfe9b"),
      confirmLabel: window.RMLI18n.t("ui.literal.9ce3bd4224c8")
    });
    return;
  }

  if (sequence !== projectDialogOpenSequence) {
    return;
  }

  await waitForBuilderMessageQueueIdle();

  if (sequence !== projectDialogOpenSequence) {
    return;
  }

  if (
    typeof elements.projectDialog.showModal ===
    "function"
  ) {
    elements.projectDialog.showModal();
  } else {
    elements.projectDialog.setAttribute(
      "open",
      ""
    );
  }

  stabilizeDialogFocus(
    elements.projectDialog
  );

  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      updateAdaptiveUtilityDialog(
        elements.projectDialog
      );
    });
  });
}

function closeProjectDialog() {
  projectDialogOpenSequence += 1;
  elements.projectDialog.classList.remove(
    "mobile-full-modal",
    "builder-settings-workspace"
  );
  const settingsPanel = document.getElementById("builder-settings-panel");
  const settingsOpen = document.getElementById("builder-settings-open");
  if (settingsPanel) settingsPanel.hidden = true;
  settingsOpen?.setAttribute("aria-expanded", "false");
  closeRmlEditorDashboardColorPicker();
  const projectDialogTitle = document.getElementById("project-dialog-title");
  const projectDialogKicker = elements.projectDialog?.querySelector(".export-dialog-header small");
  if (projectDialogTitle) projectDialogTitle.textContent = window.RMLI18n.t("{{i18n:js.presentation.83e22c2a18d3}}");
  if (projectDialogKicker) projectDialogKicker.textContent = rmlBuilderProfilePresentation?.displayName || window.RMLI18n.t("index.text.da6bafbab43a");

  if (
    typeof elements.projectDialog.close ===
    "function"
  ) {
    elements.projectDialog.close();
  } else {
    elements.projectDialog.removeAttribute(
      "open"
    );
  }
}

let activeBuilderMessageResolver = null;
let builderMessageQueueTail =
  Promise.resolve();

async function waitForBuilderMessageQueueIdle() {

  while (true) {
    const observedTail =
      builderMessageQueueTail;
    await observedTail;
    if (
      observedTail ===
        builderMessageQueueTail
    ) {
      return;
    }
  }
}

function normalizedBuilderMessageTone(tone) {
  return ["warning", "danger", "info", "success"].includes(tone)
    ? tone
    : "info";
}

function resolveBuilderMessage(
  accepted,
  closeDialog = true
) {
  const resolve =
    activeBuilderMessageResolver;
  activeBuilderMessageResolver = null;

  if (
    closeDialog &&
    elements.builderMessageDialog?.open
  ) {
    elements.builderMessageDialog.close();
  }

  resolve?.(Boolean(accepted));
}

function presentBuilderMessage({
  tone = "info",
  kicker = window.RMLI18n.t("ui.auto.62cffdf31d52"),
  title = window.RMLI18n.t("ui.auto.f033cbfa9d5e"),
  message = "",
  details = "",
  confirmLabel = window.RMLI18n.t("index.text.9d9b264625a1"),
  cancelLabel = window.RMLI18n.t("index.text.02bc50efcb1e"),
  showCancel = true
} = {}) {
  const dialog =
    elements.builderMessageDialog;

  if (!dialog) {
    console.warn(
      window.RMLI18n.t("ui.literal.3649586735e9")
    );
    return Promise.resolve(false);
  }

  const normalizedTone =
    normalizedBuilderMessageTone(tone);
  dialog.dataset.tone = normalizedTone;
  elements.builderMessageKicker.textContent =
    kicker;
  elements.builderMessageTitle.textContent =
    title;
  elements.builderMessageCopy.textContent =
    message;
  elements.builderMessageDetails.textContent =
    details;
  elements.builderMessageDetails.hidden =
    !details;
  elements.builderMessageConfirm.textContent =
    confirmLabel;
  elements.builderMessageConfirm.dataset.tone =
    normalizedTone;
  elements.builderMessageCancel.textContent =
    cancelLabel;
  elements.builderMessageCancel.hidden =
    !showCancel;

  const result = new Promise(resolve => {
    activeBuilderMessageResolver =
      resolve;
  });

  if (
    typeof dialog.showModal ===
    "function"
  ) {
    dialog.showModal();
  } else {
    dialog.setAttribute("open", "");
  }

  requestAnimationFrame(() => {
    const focusTarget = showCancel
      ? elements.builderMessageCancel
      : elements.builderMessageConfirm;

    try {
      focusTarget.focus({
        preventScroll: true
      });
    } catch {
      focusTarget.focus();
    }
  });

  return result;
}

function showBuilderMessage(options = {}) {

  const present = () =>
    presentBuilderMessage(options);
  const queued =
    builderMessageQueueTail.then(
      present,
      present
    );
  builderMessageQueueTail = queued.then(
    () => undefined,
    error => {
      console.error(
        window.RMLI18n.t("ui.literal.0474185db40b"),
        error
      );
    }
  );
  return queued;
}

function confirmBuilderAction(options) {
  return showBuilderMessage({
    tone: "warning",
    kicker: window.RMLI18n.t("ui.auto.4756c4ebe0d2"),
    title: window.RMLI18n.t("ui.auto.f033cbfa9d5e"),
    message:
      window.RMLI18n.t("ui.auto.50ba28e251fb"),
    ...options,
    showCancel: true
  });
}

function showBuilderNotice(options) {
  return showBuilderMessage({
    tone: "info",
    kicker: window.RMLI18n.t("ui.auto.1123f7ce9177"),
    title: window.RMLI18n.t("ui.auto.8e6fdbf03194"),
    confirmLabel: window.RMLI18n.t("ui.literal.9ce3bd4224c8"),
    ...options,
    showCancel: false
  });
}

function exposeBuilderDialogBridge() {
  Object.defineProperty(
    window,
    window.RMLI18n.t("ui.literal.8446b0a1bddf"),
    {
      value: Object.freeze({
        confirm: options =>
          confirmBuilderAction(options),
        notice: options =>
          showBuilderNotice(options)
      }),
      writable: false,
      enumerable: false,
      configurable: true
    }
  );
}

function builderHasActiveProject() {
  if (state.nodes.length > 0) {
    return true;
  }

  if (
    Object.keys(
      state.extensions || {}
    ).length > 0
  ) {
    return true;
  }

  return Object.keys(
    DEFAULT_METADATA
  ).some(
    key =>
      key !== "includeGuide" &&
      String(
        state.metadata?.[key] ?? ""
      ) !==
      String(
        DEFAULT_METADATA[key] ?? ""
      )
  );
}

async function saveProjectJson() {
  try {
    setProjectFileStatus(
      window.RMLI18n.t("ui.literal.10379b13cd5b")
    );

    captureVisibleBuilderPage(
      "save-json",
      true
    );
    recordPageState(
      "json.save-snapshot",
      { page: state.activePage }
    );

    const portableProject =
      createProjectDocument(
        true,
        false,
        {
          includePresentationState:
            false
        }
      );
    const fingerprint =
      projectIdentityFingerprint(
        state.projectId
      );
    rememberJsonPage(
      fingerprint,
      state.activePage,
      "save-json"
    );
    recordPageState(
      "json.save-fingerprint",
      {
        fingerprint,
        page: state.activePage
      }
    );

    const compressed =
      await createCompressedJsonBlob(
        portableProject
      );
    const filename =
      `${projectFileBaseName()}` +
      ".rmlproject.json.gz";

    downloadBlob(
      compressed.blob,
      filename
    );

    const reduction =
      compressed.jsonBytes > 0
        ? Math.max(
            0,
            Math.round(
              (1 -
                compressed.compressedBytes /
                  compressed.jsonBytes) *
                100
            )
          )
        : 0;
    setProjectFileStatus(
      `Saved ${filename} with GZIP compression${reduction > 0 ? ` (${reduction}% smaller)` : ""}.`,
      "success"
    );
  } catch (error) {
    setProjectFileStatus(
      error instanceof Error
        ? error.message
        : String(error),
      "error"
    );
  }
}

async function loadProjectJsonFile(
  file
) {
  if (!file) {
    return;
  }

  const loadSession =
    ++activeProjectLoadSession;
  let documentKind = "project";

  setProjectFileStatus(
    `Reading and validating ${file.name}…`
  );
  setProjectLoadProgress(
    true,
    {
      progress: 8,
      stage:
        window.RMLI18n.t("ui.literal.02c189378c61")
    }
  );

  try {
    if (
      file.size >
      PROJECT_FILE_MAX_BYTES
    ) {
      throw new Error(
        `The selected file is larger than the ${formatProjectByteLimit(PROJECT_FILE_MAX_BYTES)} project limit.`
      );
    }

    releaseIdleBuilderMemory({
      discardGeneratedBuild: true
    });

    await paintBuilderUi();

    const projectFile =
      await readJsonFileSource(
        file,
        file.name
      );
    let projectSource =
      projectFile.value;

    if (
      loadSession !==
        activeProjectLoadSession
    ) {
      return;
    }

    documentKind =
      projectModalJsonDocumentKind(
        projectSource
      );

    if (
      documentKind ===
        "saved-api-composites"
    ) {
      setProjectLoadProgress(
        true,
        {
          progress: 32,
          stage:
            window.RMLI18n.t("ui.literal.6f86883b93f3")
        }
      );
      closeProjectDialog();
      setProjectLoadProgress(false);
      await paintBuilderUi();

      await ensureLazyScriptBundle(
        "runtime-core"
      );

      const host =
        window.RMLDynamicGraphHost;
      if (
        projectFile.uncompressedBytes >
          SAVED_API_COMPOSITE_IMPORT_MAX_BYTES
      ) {
        throw new Error(
          window.RMLI18n.t("ui.literal.4292dd2d5a90")
        );
      }
      if (
        !host ||
        typeof host.importSavedApiComposites !==
          "function"
      ) {
        throw new Error(
          window.RMLI18n.t("ui.literal.800dd7278646")
        );
      }

      const importPromise =
        host.importSavedApiComposites(
          projectSource
        );

      projectFile.value = null;
      projectSource = null;
      const imported = await importPromise;
      if (
        loadSession !==
          activeProjectLoadSession
      ) {
        return;
      }

      const importSummary =
        imported?.summary || null;
      const replacedInstances = Number(
        importSummary?.instancesReplaced || 0
      );
      const replacementErrors = Number(
        importSummary?.instanceUpdateErrors || 0
      );
      const declinedReplacements = Number(
        importSummary?.instanceUpdatesDeclined || 0
      );
      const linkedByName = Number(
        importSummary?.instancesLinkedByName || 0
      );
      const disconnectedWires = Number(
        importSummary?.disconnectedWires || 0
      );
      const omittedApiNodeDetails =
        Array.isArray(
          importSummary
            ?.omittedApiNodeDetails
        )
          ? importSummary
              .omittedApiNodeDetails
          : [];
      const omittedApiNodes = Math.max(
        omittedApiNodeDetails.length,
        Number(
          importSummary?.omittedApiNodes ||
          0
        )
      );
      const omittedApiConnections =
        Math.max(
          0,
          Number(
            importSummary
              ?.omittedApiConnections ||
            0
          )
        );
      const offlinePreservationDetails =
        Array.isArray(
          importSummary
            ?.offlinePreservationDetails
        )
          ? importSummary
              .offlinePreservationDetails
          : [];
      const offlinePreservedApiNodes =
        Math.max(
          offlinePreservationDetails.reduce(
            (total, value) =>
              total + Math.max(
                0,
                Number(
                  value?.nodeCount
                ) || 0
              ),
            0
          ),
          Number(
            importSummary
              ?.offlinePreservedApiNodes ||
            0
          )
        );
      const omissionDetails =
        omittedApiNodeDetails.map(item => {
          const connections =
            (Array.isArray(
              item
                ?.disconnectedConnectionIds
            )
              ? item
                  .disconnectedConnectionIds
              : [])
              .map(value =>
                String(
                  typeof value === "string"
                    ? value
                    : value
                        ?.connectionId ||
                      ""
                )
              )
              .filter(Boolean);
          return `${String(item?.compositeName || window.RMLI18n.t("ui.literal.8030a124d0bc"))}: '${String(item?.nodeName || item?.nodeId || window.RMLI18n.t("ui.literal.79bf95179598"))}' [${String(item?.operatorId || "unknown operator")}] at ${String(item?.path || "runtime-root")}/${String(item?.nodeId || "<unknown>")}${connections.length > 0 ? `; removed connections: ${connections.join(", ")}` : "; no connected wires were removed"}`;
        });
      setProjectFileStatus(
        importSummary
          ? `Composite import completed: ${Number(importSummary.added || 0).toLocaleString(window.RMLI18n?.language || undefined)} new, ${Number(importSummary.updated || 0).toLocaleString(window.RMLI18n?.language || undefined)} updated, ${Number(importSummary.unchanged || 0).toLocaleString(window.RMLI18n?.language || undefined)} unchanged and ${Number(importSummary.discarded || 0).toLocaleString(window.RMLI18n?.language || undefined)} discarded.${omittedApiNodes > 0 ? ` ${omittedApiNodes.toLocaleString(window.RMLI18n?.language || undefined)} unavailable API node${omittedApiNodes === 1 ? " was" : "s were"} omitted with ${omittedApiConnections.toLocaleString(window.RMLI18n?.language || undefined)} dependent connection${omittedApiConnections === 1 ? "" : "s"}; the remaining graph was loaded.` : ""}${offlinePreservedApiNodes > 0 ? ` ${offlinePreservedApiNodes.toLocaleString(window.RMLI18n?.language || undefined)} API node${offlinePreservedApiNodes === 1 ? " was" : "s were"} preserved from complete stored portable contracts because neither cache nor Live could be verified.` : ""}${replacedInstances > 0 ? ` ${replacedInstances.toLocaleString(window.RMLI18n?.language || undefined)} placed instance${replacedInstances === 1 ? " was" : "s were"} replaced.${linkedByName > 0 ? ` ${linkedByName.toLocaleString(window.RMLI18n?.language || undefined)} matched by exact normalized name and received the imported fingerprint.` : ""}` : declinedReplacements > 0 ? ` The Library import remains stored; ${declinedReplacements.toLocaleString(window.RMLI18n?.language || undefined)} optional replacement${declinedReplacements === 1 ? " was" : "s were"} declined and the open project was not changed.` : ` ${window.RMLI18n.t("ui.literal.4a44cc28eabb")}`}${disconnectedWires > 0 ? ` ${disconnectedWires.toLocaleString(window.RMLI18n?.language || undefined)} obsolete outer wire${disconnectedWires === 1 ? " was" : "s were"} removed after confirmation and must be reconnected where still needed.` : ""}${replacementErrors > 0 ? ` ${replacementErrors.toLocaleString(window.RMLI18n?.language || undefined)} graph replacement${replacementErrors === 1 ? " failed" : "s failed"} atomically; the Library import remains stored.` : ""}`
          : `Imported ${Number(imported?.length || 0).toLocaleString(window.RMLI18n?.language || undefined)} Saved API Composite${imported?.length === 1 ? "" : "s"}. The open project was not changed.`,
        replacementErrors > 0 ||
        omittedApiNodes > 0 ||
        offlinePreservedApiNodes > 0
          ? "warning"
          : "success"
      );
      if (omittedApiNodes > 0) {
        await showBuilderNotice({
          tone: "warning",
          kicker:
            window.RMLI18n.t("ui.auto.1de8c49c903a"),
          title:
            omittedApiNodes === 1
              ? window.RMLI18n.t("ui.literal.76dd9118051b")
              : window.RMLI18n.t("ui.literal.4ff6413bab9c"),
          message:
            `The remaining Saved Composite graph was imported successfully. ${omittedApiNodes.toLocaleString(window.RMLI18n?.language || undefined)} unavailable API node${omittedApiNodes === 1 ? " was" : "s were"} neither reconstructed automatically nor replaceable with a compatible current node and ${omittedApiNodes === 1 ? "was" : "were"} therefore omitted.`,
          details:
            `${omittedApiConnections.toLocaleString(window.RMLI18n?.language || undefined)} dependent connection${omittedApiConnections === 1 ? " was" : "s were"} removed with ${omittedApiConnections === 1 ? "it" : "them"}; unrelated nodes and routes were preserved. ${omissionDetails.slice(0, 12).join(" | ")}${omissionDetails.length > 12 ? ` | and ${(omissionDetails.length - 12).toLocaleString(window.RMLI18n?.language || undefined)} more` : ""}`,
          confirmLabel: window.RMLI18n.t("ui.literal.9ce3bd4224c8")
        });
      } else if (
        offlinePreservedApiNodes > 0
      ) {
        await showBuilderNotice({
          tone: "warning",
          kicker:
            window.RMLI18n.t("ui.auto.b025802914f0"),
          title:
            window.RMLI18n.t("ui.auto.3624b4a635ca"),
          message:
            `The Saved Composite was imported instead of being rejected. ${offlinePreservedApiNodes.toLocaleString(window.RMLI18n?.language || undefined)} API node${offlinePreservedApiNodes === 1 ? " was" : "s were"} retained from complete, conflict-free stored contracts because the verified cache did not provide a usable current catalog.`,
          details:
            `${offlinePreservationDetails.map(value => `${String(value?.compositeName || window.RMLI18n.t("ui.literal.8030a124d0bc"))}: ${Math.max(0, Number(value?.nodeCount) || 0).toLocaleString(window.RMLI18n?.language || undefined)} preserved API node${Number(value?.nodeCount) === 1 ? "" : "s"}`).join(" | ")} No node was guessed or deleted merely because the catalog was unavailable. The Builder will reconcile these contracts when a verified cache or Live catalog becomes available.`,
          confirmLabel: window.RMLI18n.t("ui.literal.9ce3bd4224c8")
        });
      }

      await openProjectDialog();
      return;
    }

    assertProjectDocumentEnvelope(
      projectSource
    );

    setProjectLoadProgress(
      true,
      {
        progress: 28,
        stage:
          window.RMLI18n.t("ui.literal.a7fbe1ad6ce2")
      }
    );

    if (
      builderHasActiveProject()
    ) {
      closeProjectDialog();
      setProjectLoadProgress(false);
      await paintBuilderUi();

      const confirmed =
        await confirmBuilderAction({
          tone: "warning",
          kicker: window.RMLI18n.t("ui.auto.af51b319fd2f"),
          title: window.RMLI18n.t("ui.auto.bfe1fa22c13b"),
          message:
            window.RMLI18n.t("ui.auto.46aa53d49d94"),
          details:
            window.RMLI18n.t("ui.literal.892667439de6"),
          confirmLabel: window.RMLI18n.t("ui.literal.bdeb47e70906")
        });

      if (
        loadSession !==
          activeProjectLoadSession
      ) {
        return;
      }

      if (!confirmed) {
        openProjectDialog();
        setProjectFileStatus(
          window.RMLI18n.t("ui.literal.0007fbe86913")
        );
        return;
      }
    } else {
      closeProjectDialog();
    }

    const workSession =
      beginBuilderWork({
        kicker:
          window.RMLI18n.t("ui.auto.10d93ab75ca6"),
        title:
          window.RMLI18n.t("ui.auto.f1fef57ce7bc"),
        message:
          window.RMLI18n.t("ui.auto.cfae88deac09"),
        detail:
          window.RMLI18n.t("ui.literal.8242f7ce08d0"),
        progress: 32,
        timeout: 120000
      });

    try {
      const prerequisites =
        await ensureProjectRuntimePrerequisites(
          projectSource,
          workSession,
          { catalogOnly: true }
        );

      updateBuilderWork(
        workSession,
        {
          kicker:
            window.RMLI18n.t("index.text.26ab7b3db86d"),
          title:
            window.RMLI18n.t("ui.auto.6e404a3c0705"),
          message:
            prerequisites.compatibilityMode
              ? window.RMLI18n.t("ui.literal.3479122351c5")
              : window.RMLI18n.t("ui.literal.afc4f665c6b9"),
          detail:
            window.RMLI18n.t("ui.literal.24a8fc950f72"),
          progress: 54
        }
      );
      await paintBuilderUi();

      const project =
        parseProjectDocument(
          projectSource
        );
      Object.defineProperty(
        project,
        "__rmlJsonFingerprint",
        {
          value:
            projectIdentityFingerprint(
              project.projectId
            ),
          writable: false,
          enumerable: false,
          configurable: true
        }
      );

      const importResult =
        await applyLoadedProjectWithFeedback(
        project,
        {
          displayName: file.name,
          workSession,
          prevalidatedPrerequisites:
            prerequisites,
          forceConfigurationPage: true
        }
      );
      if (
        loadSession !==
          activeProjectLoadSession
      ) {
        return;
      }
      const importWarnings =
        Array.isArray(prerequisites?.importValidationDiagnostics)
          ? prerequisites.importValidationDiagnostics
          : [];
      setProjectFileStatus(
        importResult?.retainedAfterImportError === true || importWarnings.length > 0
          ? window.RMLI18n.t("import.loaded_with_runtime_errors")
          : `Loaded ${file.name} successfully.`,
        importResult?.retainedAfterImportError === true || importWarnings.length > 0
          ? "warning"
          : "success"
      );
    } catch (error) {
      finishBuilderWork(
        workSession
      );
      throw error;
    }
  } catch (error) {
    if (
      loadSession !==
        activeProjectLoadSession
    ) {
      return;
    }

    const importCancelled =
      error?.code ===
        "RML_PROJECT_IMPORT_CANCELLED";
    const syntaxError = error instanceof SyntaxError;
    if (!importCancelled) {
      console.error(
        syntaxError
          ? "[RML IMPORT JSON SYNTAX ERROR]"
          : "[RML IMPORT INTERNAL ERROR — JSON SYNTAX WAS ACCEPTED]",
        error
      );
    }
    if (!elements.projectDialog.open) openProjectDialog();
    setProjectFileStatus(
      importCancelled
        ? String(error?.message || window.RMLI18n.t("ui.literal.8380b64d7286"))
        : syntaxError
          ? window.RMLI18n.format("import.syntax_error", {
              message: error instanceof Error ? error.message : String(error)
            })
          : window.RMLI18n.t("import.internal_before_apply"),
      importCancelled ? "" : "error"
    );
  } finally {
    if (
      loadSession ===
        activeProjectLoadSession
    ) {
      setProjectLoadProgress(false);
    }
    elements.projectFileInput.value =
      "";
  }
}

let crc32Table = null;

function getCrc32Table() {
  if (crc32Table) {
    return crc32Table;
  }

  crc32Table = new Uint32Array(256);
  for (let index = 0; index < 256; index += 1) {
    let value = index;
    for (let bit = 0; bit < 8; bit += 1) {
      value =
        (value & 1) !== 0
          ? 0xedb88320 ^ (value >>> 1)
          : value >>> 1;
    }
    crc32Table[index] = value >>> 0;
  }
  return crc32Table;
}

function crc32(bytes) {
  const table = getCrc32Table();
  let value = 0xffffffff;
  for (const byte of bytes) {
    value =
      table[(value ^ byte) & 0xff] ^
      (value >>> 8);
  }
  return (value ^ 0xffffffff) >>> 0;
}

function zipDateTime(date = new Date()) {
  const year = Math.max(1980, date.getFullYear());
  return {
    time:
      (date.getHours() << 11) |
      (date.getMinutes() << 5) |
      Math.floor(date.getSeconds() / 2),
    date:
      ((year - 1980) << 9) |
      ((date.getMonth() + 1) << 5) |
      date.getDate()
  };
}

function createZipBlob(files) {
  const encoder = new TextEncoder();
  const localParts = [];
  const centralParts = [];
  const timestamp = zipDateTime();
  let localOffset = 0;
  let centralSize = 0;

  for (const file of files) {
    const nameBytes = encoder.encode(file.name);
    const rawContent = file.content;
    const contentBytes = rawContent instanceof Uint8Array
      ? rawContent
      : rawContent instanceof ArrayBuffer
        ? new Uint8Array(rawContent)
        : ArrayBuffer.isView(rawContent)
          ? new Uint8Array(
              rawContent.buffer,
              rawContent.byteOffset,
              rawContent.byteLength
            )
          : encoder.encode(String(rawContent ?? ""));
    const checksum = crc32(contentBytes);

    const localHeader = new Uint8Array(
      30 + nameBytes.length
    );
    const localView = new DataView(
      localHeader.buffer
    );
    localView.setUint32(0, 0x04034b50, true);
    localView.setUint16(4, 20, true);
    localView.setUint16(6, 0x0800, true);
    localView.setUint16(8, 0, true);
    localView.setUint16(10, timestamp.time, true);
    localView.setUint16(12, timestamp.date, true);
    localView.setUint32(14, checksum, true);
    localView.setUint32(18, contentBytes.length, true);
    localView.setUint32(22, contentBytes.length, true);
    localView.setUint16(26, nameBytes.length, true);
    localView.setUint16(28, 0, true);
    localHeader.set(nameBytes, 30);

    localParts.push(
      localHeader,
      contentBytes
    );

    const centralHeader = new Uint8Array(
      46 + nameBytes.length
    );
    const centralView = new DataView(
      centralHeader.buffer
    );
    centralView.setUint32(0, 0x02014b50, true);
    centralView.setUint16(4, 20, true);
    centralView.setUint16(6, 20, true);
    centralView.setUint16(8, 0x0800, true);
    centralView.setUint16(10, 0, true);
    centralView.setUint16(12, timestamp.time, true);
    centralView.setUint16(14, timestamp.date, true);
    centralView.setUint32(16, checksum, true);
    centralView.setUint32(20, contentBytes.length, true);
    centralView.setUint32(24, contentBytes.length, true);
    centralView.setUint16(28, nameBytes.length, true);
    centralView.setUint16(30, 0, true);
    centralView.setUint16(32, 0, true);
    centralView.setUint16(34, 0, true);
    centralView.setUint16(36, 0, true);
    centralView.setUint32(38, 0, true);
    centralView.setUint32(42, localOffset, true);
    centralHeader.set(nameBytes, 46);
    centralParts.push(centralHeader);

    localOffset +=
      localHeader.length +
      contentBytes.length;
    centralSize += centralHeader.length;
  }

  const endRecord = new Uint8Array(22);
  const endView = new DataView(
    endRecord.buffer
  );
  endView.setUint32(0, 0x06054b50, true);
  endView.setUint16(4, 0, true);
  endView.setUint16(6, 0, true);
  endView.setUint16(8, files.length, true);
  endView.setUint16(10, files.length, true);
  endView.setUint32(12, centralSize, true);
  endView.setUint32(16, localOffset, true);
  endView.setUint16(20, 0, true);

  return new Blob(
    [
      ...localParts,
      ...centralParts,
      endRecord
    ],
    {
      type: "application/zip"
    }
  );
}

function safeArchiveSegment(
  value,
  fallback = window.RMLI18n.t("ui.literal.8eefdd52ad2d")
) {
  const normalized = String(value || "")
    .trim()
    .replace(/[<>:"/\\|?*\u0000-\u001F]/g, "_")
    .replace(/[. ]+$/g, "")
    .slice(0, 120);

  return normalized || fallback;
}

function safeArchiveRelativePath(
  value,
  fallback = window.RMLI18n.t("ui.literal.2d4e6341d5cd")
) {
  const parts = String(value || "")
    .replace(/\\/g, "/")
    .split("/")
    .map(part => part.trim())
    .filter(part =>
      part &&
      part !== "." &&
      part !== ".."
    )
    .map(part =>
      safeArchiveSegment(
        part,
        window.RMLI18n.t("ui.literal.8eefdd52ad2d")
      )
    );

  return parts.join("/") ||
    safeArchiveSegment(
      fallback,
      window.RMLI18n.t("ui.literal.2d4e6341d5cd")
    );
}

function auxiliaryProjectFolder(
  project,
  index
) {
  return safeArchiveRelativePath(
    project?.folder ||
      project?.name ||
      `Library-${index + 1}`,
    `Library-${index + 1}`
  );
}

function generateMultiProjectReadme(
  baseName,
  auxiliaryProjects
) {
  const projectLines = auxiliaryProjects
    .map((project, index) => {
      const folder = auxiliaryProjectFolder(
        project,
        index
      );
      const name = safeArchiveSegment(
        project.name ||
        project.assemblyName,
        `Library-${index + 1}`
      );
      const deployment = String(
        project.deployDirectory ||
        "rml_libs"
      );

      return `- \`${folder}/${name}.csproj\` → builds \`${name}.dll\` and deploys it to \`${deployment}\`.`;
    })
    .join("\n");

  return `# ${baseName} generated RML project

This archive contains independently compiled projects because early Harmony patches must be loaded before normal RML mods.

## Projects

- \`Mod/${baseName}.csproj\` → builds \`${baseName}.dll\` and deploys it to \`rml_mods\`.
${projectLines}

## Build

Run \`build.ps1\` on Windows or \`build.sh\` on Linux/macOS. Each project also supports a custom Resonite path:

\`dotnet build <project.csproj> -c Release -p:ResonitePath="<Resonite installation>"\`

Set \`-p:DeployToResonite=false\` to compile without copying the resulting DLL.

## Harmony load phases

- Graph-driven Harmony Patch Event and scanner-generated Harmony API calls remain in the main mod DLL and register at mod \`OnEngineInit\`.
- Early Harmony Patch Library sources compile into the separate \`rml_libs\` DLL and are discovered through \`RmlPatchAssemblyAttribute\` before \`rml_mods\` are loaded.
- Early patch libraries cannot call generated graph \`Emit...\` methods or depend on runtime configuration values from the main mod.
`;
}

function generateBuildPowerShell(
  baseName,
  auxiliaryProjects
) {
  const projects = [
    ...auxiliaryProjects.map((project, index) => {
      const folder = auxiliaryProjectFolder(
        project,
        index
      );
      const name = safeArchiveSegment(
        project.name ||
        project.assemblyName,
        `Library-${index + 1}`
      );
      return `./${folder}/${name}.csproj`;
    }),
    `./Mod/${baseName}.csproj`
  ];

  return `$ErrorActionPreference = window.RMLI18n.t("ui.auto.a7d79d1d05da")

$projects = @(
${projects.map(project => `    "${project}"`).join(",\n")}
)

foreach ($project in $projects) {
    dotnet build $project -c Release @args
    if ($LASTEXITCODE -ne 0) {
        exit $LASTEXITCODE
    }
}
`;
}

function generateBuildShell(
  baseName,
  auxiliaryProjects
) {
  const projects = [
    ...auxiliaryProjects.map((project, index) => {
      const folder = auxiliaryProjectFolder(
        project,
        index
      );
      const name = safeArchiveSegment(
        project.name ||
        project.assemblyName,
        `Library-${index + 1}`
      );
      return `./${folder}/${name}.csproj`;
    }),
    `./Mod/${baseName}.csproj`
  ];

  return `#!/usr/bin/env sh
set -eu

${projects
    .map(project =>
      `dotnet build "${project}" -c Release "$@"`
    )
    .join("\n")}
`;
}

function buildSelectedExportFiles(
  includeCs,
  includeCsproj
) {
  requireGeneratedGuidance();
  const baseName = generatedBaseName();
  const graphFiles =
    getAdditionalGeneratedSourceFiles();
  const auxiliaryProjects =
    getAdditionalGeneratedProjects();

  if (!includeCs && !includeCsproj) {
    return {
      files: [],
      multiProject:
        auxiliaryProjects.length > 0,
      auxiliaryProjects
    };
  }

  if (auxiliaryProjects.length === 0) {
    const files = [];

    if (includeCs) {
      files.push({
        name: `${baseName}.cs`,
        content: generateCode(),
        type:
          "text/plain;charset=utf-8"
      });
      files.push(...graphFiles);
    }

    if (includeCsproj) {
      files.push({
        name: `${baseName}.csproj`,
        content: generateProjectFile(),
        type:
          "application/xml;charset=utf-8"
      });
    }

    return {
      files,
      multiProject: false,
      auxiliaryProjects
    };
  }

  const root = safeArchiveSegment(
    `${baseName}-RML-Project`,
    window.RMLI18n.t("ui.literal.ede9859c0c93")
  );
  const files = [];
  const usedPaths = new Set();

  const addFile = file => {
    const requested = safeArchiveRelativePath(
      file.name,
      window.RMLI18n.t("ui.literal.f3b317568b28")
    );
    const extensionIndex =
      requested.lastIndexOf(".");
    const stem = extensionIndex > 0
      ? requested.slice(0, extensionIndex)
      : requested;
    const extension = extensionIndex > 0
      ? requested.slice(extensionIndex)
      : "";
    let unique = requested;
    let suffix = 2;

    while (
      usedPaths.has(
        unique.toLowerCase()
      )
    ) {
      unique = `${stem}-${suffix}${extension}`;
      suffix += 1;
    }

    usedPaths.add(
      unique.toLowerCase()
    );
    files.push({
      ...file,
      name: `${root}/${unique}`
    });
  };

  if (includeCs) {
    addFile({
      name: `Mod/${baseName}.cs`,
      content: generateCode(),
      type:
        "text/plain;charset=utf-8"
    });

    for (const graphFile of graphFiles) {
      addFile({
        ...graphFile,
        name:
          `Mod/${safeArchiveRelativePath(
            graphFile.name,
            `${baseName}.NodeGraph.cs`
          )}`
      });
    }

    auxiliaryProjects.forEach(
      (project, index) => {
        const folder =
          auxiliaryProjectFolder(
            project,
            index
          );

        for (const file of
          project.files || []) {
          addFile({
            ...file,
            name:
              `${folder}/${safeArchiveRelativePath(
                file.name,
                window.RMLI18n.t("ui.literal.1d3111a4d738")
              )}`
          });
        }
      }
    );
  }

  if (includeCsproj) {
    addFile({
      name: `Mod/${baseName}.csproj`,
      content: generateProjectFile(),
      type:
        "application/xml;charset=utf-8"
    });

    auxiliaryProjects.forEach(
      (project, index) => {
        const folder =
          auxiliaryProjectFolder(
            project,
            index
          );
        const projectName =
          safeArchiveSegment(
            project.name ||
            project.assemblyName,
            `Library-${index + 1}`
          );

        addFile({
          name:
            `${folder}/${projectName}.csproj`,
          content:
            generateAuxiliaryProjectFile(
              project
            ),
          type:
            "application/xml;charset=utf-8"
        });
      }
    );

    addFile({
      name: "build.ps1",
      content:
        generateBuildPowerShell(
          baseName,
          auxiliaryProjects
        ),
      type:
        "text/plain;charset=utf-8"
    });
    addFile({
      name: "build.sh",
      content:
        generateBuildShell(
          baseName,
          auxiliaryProjects
        ),
      type:
        "text/plain;charset=utf-8"
    });
  }

  addFile({
    name: window.RMLI18n.t("ui.literal.8ec9a00bfd09"),
    content:
      generateMultiProjectReadme(
        baseName,
        auxiliaryProjects
      ),
    type:
      "text/markdown;charset=utf-8"
  });

  return {
    files,
    multiProject: true,
    auxiliaryProjects
  };
}

function generatedArtifactKind(
  fileName,
  mimeType = ""
) {
  const name = String(fileName || "")
    .toLowerCase();
  const type = String(mimeType || "")
    .toLowerCase();

  if (name.endsWith(".dll")) {
    return {
      kind: "binary",
      kindLabel: ".NET assembly",
      badge: "DLL"
    };
  }

  if (name.endsWith(".cs")) {
    return {
      kind: "source",
      kindLabel: "C# source",
      badge: "CS"
    };
  }

  if (
    name.endsWith(".csproj") ||
    type.includes("xml")
  ) {
    return {
      kind: "project",
      kindLabel: ".NET project",
      badge: window.RMLI18n.t("ui.literal.0963d5c6b941")
    };
  }

  if (
    name.endsWith(".ps1") ||
    name.endsWith(".sh")
  ) {
    return {
      kind: "build",
      kindLabel: window.RMLI18n.t("ui.literal.7db6ca47d21a"),
      badge: window.RMLI18n.t("ui.literal.9b8dfdff736c")
    };
  }

  if (
    name.endsWith(".md") ||
    type.includes("markdown")
  ) {
    return {
      kind: "documentation",
      kindLabel: window.RMLI18n.t("ui.literal.9e9cf3221a30"),
      badge: window.RMLI18n.t("ui.literal.92ed52dada39")
    };
  }

  return {
    kind: "file",
    kindLabel: window.RMLI18n.t("index.text.be5105d167c2"),
    badge: window.RMLI18n.t("ui.literal.b4915d3a7ef8")
  };
}

function stripGeneratedArchiveRoot(
  archivePath,
  multiProject
) {
  const normalized =
    String(archivePath || "")
      .replace(/\\/g, "/")
      .replace(/^\/+/, "");

  if (!multiProject) {
    return normalized;
  }

  const separator =
    normalized.indexOf("/");

  return separator >= 0
    ? normalized.slice(separator + 1)
    : normalized;
}

function generatedProjectDescriptors(
  result
) {
  const baseName = generatedBaseName();
  const descriptors = [
    {
      id: "main-mod",
      folder: result.multiProject
        ? window.RMLI18n.t("ui.literal.f388dbfb78ec")
        : "",
      label: `${baseName} · Main mod`,
      assemblyName: baseName,
      version:
        projectVersionMetadata().version,
      deployDirectory: "rml_mods",
      role: "rml-mod"
    }
  ];

  result.auxiliaryProjects.forEach(
    (project, index) => {
      descriptors.push({
        id:
          String(
            project.id ||
            `auxiliary-${index + 1}`
          ),
        folder:
          auxiliaryProjectFolder(
            project,
            index
          ),
        label:
          String(
            project.name ||
            project.assemblyName ||
            `Library ${index + 1}`
          ),
        assemblyName:
          String(
            project.assemblyName ||
            project.name ||
            `Library-${index + 1}`
          ),
        version:
          projectVersionMetadata().version,
        deployDirectory:
          String(
            project.deployDirectory ||
            "rml_libs"
          ),
        role:
          String(
            project.role ||
            "auxiliary-library"
          )
      });
    }
  );

  return descriptors;
}

function buildGeneratedArtifactCatalog(
  includeCs = true,
  includeCsproj = true
) {
  const result =
    buildSelectedExportFiles(
      includeCs,
      includeCsproj
    );
  const projects =
    generatedProjectDescriptors(result);
  const projectFolders = projects
    .filter(project => project.folder)
    .sort(
      (left, right) =>
        right.folder.length -
        left.folder.length
    );

  const artifacts = result.files.map(
    (file, index) => {
      const relativePath =
        stripGeneratedArchiveRoot(
          file.name,
          result.multiProject
        );
      const normalizedPath =
        relativePath.replace(/\\/g, "/");
      let project;

      if (!result.multiProject) {
        project = projects[0];
      } else {
        project = projectFolders.find(
          candidate =>
            normalizedPath ===
              candidate.folder ||
            normalizedPath.startsWith(
              `${candidate.folder}/`
            )
        ) || null;
      }

      const kind =
        generatedArtifactKind(
          normalizedPath,
          file.type
        );

      return {
        key:
          String(file.name ||
            `generated-${index}`),
        archivePath:
          String(file.name || ""),
        relativePath:
          normalizedPath,
        fileName:
          normalizedPath
            .split("/")
            .pop() ||
          normalizedPath,
        content: file.content ?? "",
        type:
          file.type ||
          "text/plain;charset=utf-8",
        ...kind,
        projectId:
          project?.id ||
          "support",
        projectLabel:
          project?.label ||
          window.RMLI18n.t("ui.literal.d6f371f8684f"),
        deployDirectory:
          project?.deployDirectory ||
          "",
        projectRole:
          project?.role ||
          "support",
        requiresResonitePath:
          kind.kind === "project"
      };
    }
  );

  return {
    ...result,
    projects,
    artifacts
  };
}

function freezeGeneratedArtifactCatalog(
  catalog
) {
  return Object.freeze({
    multiProject:
      catalog?.multiProject === true,
    projects: Object.freeze(
      (Array.isArray(catalog?.projects)
        ? catalog.projects
        : [])
        .map(project => Object.freeze({
          ...project
        }))
    ),
    artifacts: Object.freeze(
      (Array.isArray(catalog?.artifacts)
        ? catalog.artifacts
        : [])
        .map(artifact => Object.freeze({
          ...artifact,
          content:
            artifact?.content ?? ""
        }))
    )
  });
}

function selectedExportFilesFromCatalog(
  catalog,
  includeCs,
  includeCsproj
) {
  const includeAny =
    includeCs || includeCsproj;
  const files = catalog.artifacts
    .filter(artifact => {
      if (artifact.kind === "source") {
        return includeCs;
      }
      if (
        artifact.kind === "project" ||
        artifact.kind === "build"
      ) {
        return includeCsproj;
      }
      return includeAny;
    })
    .map(artifact => ({
      name: artifact.archivePath,
      content: artifact.content,
      type: artifact.type,
      projectId: artifact.projectId,
      projectLabel: artifact.projectLabel,
      deployDirectory:
        artifact.deployDirectory,
      projectRole: artifact.projectRole
    }));

  return {
    files,
    multiProject:
      catalog.multiProject === true,
    projects: catalog.projects,
    artifacts: catalog.artifacts
  };
}

function browserCompilerReferenceSelectionError(
  message
) {
  const error = new Error(message);
  error.code = "RML_COMPILER_REFERENCES_REQUIRED";
  return error;
}

function normalizedAssemblyFileName(
  value
) {
  return String(value || "")
    .trim()
    .split(",", 1)[0]
    .replace(/\.dll$/i, "")
    .toLowerCase();
}

function selectedBrowserCompilerReferences() {
  return [...browserCompilerReferenceFiles.values()]
    .sort((left, right) =>
      String(left.name || "").localeCompare(
        String(right.name || ""),
        "en"
      )
    );
}

function browserCompilerReferencePath(file) {
  return String(
    browserCompilerReferencePaths.get(file) ||
    file?.webkitRelativePath ||
    file?.name ||
    ""
  );
}

function browserCompilerDllCandidates(files) {
  return Object.freeze(
    [...(files || [])].filter(file =>
      /\.dll$/i.test(
        String(file?.name || "")
      )
    )
  );
}

function retainSelectedBrowserCompilerDirectoryFiles() {
  if (browserCompilerDirectoryFiles.length === 0) {
    return;
  }
  const selected = new Set(
    selectedBrowserCompilerReferences()
  );
  browserCompilerDirectoryFiles =
    Object.freeze(
      browserCompilerDirectoryFiles.filter(
        file => selected.has(file)
      )
    );
}

function renderBrowserCompilerReferenceList() {
  const host =
    elements.exportCompilerReferenceList;
  if (!host) return;

  const references =
    selectedBrowserCompilerReferences();
  host.hidden = references.length === 0;
  if (references.length === 0) {
    host.replaceChildren();
    return;
  }

  const fragment =
    document.createDocumentFragment();
  for (const file of references) {
    const item = document.createElement("div");
    item.className =
      "export-compiler-reference-item";

    const name = document.createElement("strong");
    name.textContent = `Found: ${file.name}`;
    item.append(name);

    const path = browserCompilerReferencePath(file);
    if (path && path !== file.name) {
      const detail = document.createElement("small");
      detail.textContent = path;
      item.append(detail);
    }

    fragment.append(item);
  }
  host.replaceChildren(fragment);
}

function requiredBrowserCompilerReferences(
  catalog
) {
  const required = new Map();
  const add = value => {
    const display = String(value || "")
      .trim()
      .split(",", 1)[0];
    const key = normalizedAssemblyFileName(
      display
    );

    if (key) {
      required.set(key, display);
    }
  };

  for (const artifact of catalog.artifacts) {
    if (artifact.kind !== "project") {
      continue;
    }

    const content = String(
      artifact.content || ""
    );
    for (const match of content.matchAll(
      /<Reference\s+Include="([^"]+)"/gi
    )) {
      add(match[1]);
    }

    if (
      /<UseWindowsForms>\s*true\s*<\/UseWindowsForms>/i
        .test(content)
    ) {
      add("System.Windows.Forms");
    }
  }

  for (
    const name of
      browserCompilerAdditionalRequiredReferences.values()
  ) {
    add(name);
  }

  return [...required.values()].sort(
    (left, right) =>
      left.localeCompare(right, "en")
  );
}

function missingBrowserCompilerReferences(
  catalog
) {
  const selected = new Set(
    selectedBrowserCompilerReferences()
      .map(file =>
        normalizedAssemblyFileName(
          file.name
        )
      )
  );

  return requiredBrowserCompilerReferences(
    catalog
  ).filter(name =>
    !selected.has(
      normalizedAssemblyFileName(name)
    )
  );
}

function browserCompilerBundledFrameworkAssembly(
  name
) {
  const key = normalizedAssemblyFileName(name);
  return (
    key === "system" ||
    key.startsWith("system.") ||
    key === "mscorlib" ||
    key === "netstandard" ||
    key === "microsoft.csharp" ||
    key === "microsoft.visualbasic" ||
    key.startsWith("microsoft.visualbasic.") ||
    key === "windowsbase"
  );
}

function missingAssembliesFromCompilerResult(
  result
) {
  const names = new Map();
  const add = value => {
    const display = String(value || "")
      .trim()
      .split(",", 1)[0]
      .replace(/\.dll$/i, "");
    const key = normalizedAssemblyFileName(display);
    if (
      key &&
      !browserCompilerBundledFrameworkAssembly(display) &&
      !browserCompilerReferenceFiles.has(`${key}.dll`) &&
      !browserCompilerReferenceFiles.has(key)
    ) {
      names.set(key, display);
    }
  };

  const discovered =
    window.RMLCompilerReferenceDiscovery
      ?.assemblyNamesFromDiagnostics?.(
        result?.diagnostics
      ) || [];
  for (const name of discovered) {
    add(name);
  }

  return [...names.values()];
}

function setBrowserCompilerSearchStatus(message) {
  if (elements.exportCompilerBuildStatus) {
    elements.exportCompilerBuildStatus.textContent =
      String(message || "");
  }
}

function selectBrowserCompilerFiles(
  files,
  missingNames,
  { invalidate = true } = {}
) {
  const discovery =
    window.RMLCompilerReferenceDiscovery;
  if (typeof discovery?.selectMissingFiles !== "function") {
    throw new Error(
      window.RMLI18n.t("ui.literal.f5d1551c114c")
    );
  }

  const result = discovery.selectMissingFiles(
    files,
    missingNames
  );
  if (result.files.length > 0) {
    addBrowserCompilerReferenceFiles(
      result.files,
      { invalidate, refresh: false }
    );
  }
  return result;
}

function requestBrowserCompilerInputFiles(
  input,
  signal = null
) {
  if (!input) return Promise.resolve([]);

  return new Promise(resolve => {
    let settled = false;
    const finish = files => {
      if (settled) return;
      settled = true;
      input.removeEventListener("change", changed);
      input.removeEventListener("cancel", cancelled);
      signal?.removeEventListener(
        "abort",
        cancelled
      );
      input.value = "";
      resolve(files);
    };
    const changed = () => finish(
      [...(input.files || [])]
    );
    const cancelled = () => finish([]);

    input.value = "";
    input.addEventListener("change", changed);
    input.addEventListener("cancel", cancelled);
    signal?.addEventListener(
      "abort",
      cancelled,
      { once: true }
    );
    if (signal?.aborted) {
      cancelled();
      return;
    }
    try {
      input.click();
    } catch {
      finish([]);
    }
  });
}

function requestBrowserCompilerDirectoryFiles(
  signal = null
) {
  return requestBrowserCompilerInputFiles(
    elements.exportCompilerDirectory,
    signal
  );
}

function captureBrowserCompilerDrop(dataTransfer) {
  const entries = [];
  for (const item of dataTransfer?.items || []) {
    if (item?.kind !== "file") continue;
    const entry =
      item.webkitGetAsEntry?.();
    if (entry) entries.push(entry);
  }

  return Object.freeze({
    entries: Object.freeze(entries),
    files: Object.freeze([
      ...(dataTransfer?.files || [])
    ])
  });
}

function readBrowserCompilerDirectoryEntries(
  directoryEntry
) {
  return new Promise(resolve => {
    const reader = directoryEntry.createReader();
    const entries = [];
    const readBatch = () => {
      reader.readEntries(batch => {
        if (batch.length === 0) {
          resolve(entries);
          return;
        }
        entries.push(...batch);
        readBatch();
      }, () => resolve(entries));
    };
    readBatch();
  });
}

function readBrowserCompilerFileEntry(entry) {
  return new Promise(resolve => {
    entry.file(
      file => resolve(file),
      () => resolve(null)
    );
  });
}

async function collectBrowserCompilerDroppedFiles(
  capture
) {
  if (capture.entries.length === 0) {
    return Object.freeze({
      files: browserCompilerDllCandidates(
        capture.files
      ),
      hasDirectory: false,
      fileCount: capture.files.length
    });
  }

  const queue = capture.entries.map(entry => ({
    entry,
    path: String(entry.name || "")
  }));
  const fileEntries = [];
  let hasDirectory = false;
  let fileCount = 0;

  for (let index = 0; index < queue.length; index += 1) {
    const current = queue[index];
    if (current.entry.isDirectory) {
      hasDirectory = true;
      const children =
        await readBrowserCompilerDirectoryEntries(
          current.entry
        );
      for (const child of children) {
        queue.push({
          entry: child,
          path: current.path
            ? `${current.path}/${child.name}`
            : String(child.name || "")
        });
      }
      setBrowserCompilerSearchStatus(
        `Reading folder tree… ${queue.length.toLocaleString()} entries found`
      );
    } else if (current.entry.isFile) {
      fileCount += 1;
      if (/\.dll$/i.test(current.entry.name || "")) {
        fileEntries.push(current);
      }
    }
  }

  const files = [];
  const batchSize = 64;
  for (
    let offset = 0;
    offset < fileEntries.length;
    offset += batchSize
  ) {
    const batch = fileEntries.slice(
      offset,
      offset + batchSize
    );
    const resolved = await Promise.all(
      batch.map(async item => ({
        file: await readBrowserCompilerFileEntry(
          item.entry
        ),
        path: item.path
      }))
    );
    for (const item of resolved) {
      if (!item.file) continue;
      files.push(item.file);
      browserCompilerReferencePaths.set(
        item.file,
        item.path
      );
    }
    setBrowserCompilerSearchStatus(
      `Reading DLL files… ${files.length.toLocaleString()}/${fileEntries.length.toLocaleString()}`
    );
  }

  return Object.freeze({
    files: Object.freeze(files),
    hasDirectory,
    fileCount
  });
}

function resetBrowserCompilerDropState() {
  browserCompilerReferenceDragDepth = 0;
  elements.exportCompilerReferenceStatus
    ?.classList.remove("is-drag-active");
}

function browserCompilerReferenceDragEnter(event) {
  event.preventDefault();
  browserCompilerReferenceDragDepth += 1;
  elements.exportCompilerReferenceStatus
    ?.classList.add("is-drag-active");
  if (event.dataTransfer) {
    event.dataTransfer.dropEffect = "copy";
  }
}

function browserCompilerReferenceDragOver(event) {
  event.preventDefault();
  if (event.dataTransfer) {
    event.dataTransfer.dropEffect = "copy";
  }
}

function browserCompilerReferenceDragLeave(event) {
  event.preventDefault();
  browserCompilerReferenceDragDepth = Math.max(
    0,
    browserCompilerReferenceDragDepth - 1
  );
  if (browserCompilerReferenceDragDepth === 0) {
    elements.exportCompilerReferenceStatus
      ?.classList.remove("is-drag-active");
  }
}

async function browserCompilerReferenceDrop(event) {
  event.preventDefault();
  event.stopPropagation();
  const capture = captureBrowserCompilerDrop(
    event.dataTransfer
  );
  resetBrowserCompilerDropState();

  if (
    capture.entries.length === 0 &&
    capture.files.length === 0
  ) {
    return;
  }

  browserCompilerReferenceSearchRunning = true;
  updateExportDialog();
  let dropError = null;
  try {
    const dropped =
      await collectBrowserCompilerDroppedFiles(
        capture
      );
    if (dropped.files.length === 0) {
      throw new Error(
        window.RMLI18n.t("ui.literal.a43028d3bdea")
      );
    }

    const catalog = buildGeneratedArtifactCatalog(
      true,
      true
    );
    const missing =
      missingBrowserCompilerReferences(catalog);

    if (dropped.hasDirectory) {
      browserCompilerDirectoryFiles =
        dropped.files;
      browserCompilerDirectoryFileCount =
        dropped.fileCount;
      browserCompilerDirectoryMatchCount = 0;
    }

    const selected = selectBrowserCompilerFiles(
      dropped.files,
      missing
    );
    if (dropped.hasDirectory) {
      browserCompilerDirectoryMatchCount =
        selected.files.length;
    }
  } catch (error) {
    dropError = error;
  } finally {
    browserCompilerReferenceSearchRunning = false;
    updateExportDialog();
    if (dropError) {
      elements.exportDownloadHint.textContent =
        dropError instanceof Error
          ? dropError.message
          : String(dropError);
      elements.exportDownloadHint.classList.add(
        "error"
      );
    }
  }
}

async function ensureBrowserCompilerReferences(
  catalog,
  request = null,
  signal = null
) {
  const assertCurrent = () => {
    if (signal?.aborted) {
      throw signal.reason ||
        exportDeliveryCancelled();
    }
    if (request) {
      assertExportRequestCurrent(
        request,
        true
      );
    }
  };
  assertCurrent();
  let missing =
    missingBrowserCompilerReferences(catalog);
  if (missing.length === 0) return;

  browserCompilerReferenceSearchRunning = true;
  setBrowserCompilerSearchStatus(
    window.RMLI18n.t("js.presentation.13b772bea046")
  );

  try {
    if (browserCompilerDirectoryFiles.length > 0) {
      assertCurrent();
      const cachedResult = selectBrowserCompilerFiles(
        browserCompilerDirectoryFiles,
        missing
      );
      browserCompilerDirectoryMatchCount +=
        cachedResult.files.length;
      missing =
        missingBrowserCompilerReferences(catalog);
    }

    if (missing.length > 0) {
      const directoryPromise =
        requestBrowserCompilerDirectoryFiles(
          signal
        );
      const directoryFiles =
        await directoryPromise;
      assertCurrent();
      if (directoryFiles.length === 0) {
        throw browserCompilerReferenceSelectionError(
          window.RMLI18n.t("ui.literal.7475400470fe")
        );
      }

      const directoryDllFiles =
        browserCompilerDllCandidates(
          directoryFiles
        );
      assertCurrent();
      browserCompilerDirectoryFiles =
        directoryDllFiles;
      browserCompilerDirectoryFileCount =
        directoryFiles.length;
      browserCompilerDirectoryMatchCount = 0;
      setBrowserCompilerSearchStatus(
        `Checking ${directoryFiles.length.toLocaleString()} folder files…`
      );
      const folderResult = selectBrowserCompilerFiles(
        directoryDllFiles,
        missing
      );
      browserCompilerDirectoryMatchCount =
        folderResult.files.length;
      missing =
        missingBrowserCompilerReferences(catalog);
    }

    if (missing.length > 0) {
      throw browserCompilerReferenceSelectionError(
        `Folder checked: ${browserCompilerDirectoryFileCount.toLocaleString()} files, ${browserCompilerDirectoryMatchCount} required DLL${browserCompilerDirectoryMatchCount === 1 ? "" : "s"} found. Still missing: ${missing.join(", ")}. Drop the missing DLLs or another folder onto the Missing DLLs field.`
      );
    }
  } finally {
    browserCompilerReferenceSearchRunning = false;
    if (elements.exportDialog?.open) {
      updateExportDialog();
    }
  }
}

function browserCompilationProjects(
  catalog
) {
  return catalog.projects.map(project => {
    const sources = catalog.artifacts
      .filter(artifact =>
        artifact.kind === "source" &&
        artifact.projectId === project.id
      )
      .map(artifact => {
        let name = artifact.relativePath;
        if (
          project.folder &&
          name.startsWith(
            `${project.folder}/`
          )
        ) {
          name = name.slice(
            project.folder.length + 1
          );
        }

        return {
          name,
          content: String(
            artifact.content || ""
          )
        };
      });
    const projectFile = catalog.artifacts.find(
      artifact =>
        artifact.kind === "project" &&
        artifact.projectId === project.id
    );
    const projectXml = String(
      projectFile?.content || ""
    );

    sources.push({
      name: window.RMLI18n.t("ui.literal.a1334ef3c0fa"),
      content:
        generatedAssemblyMetadataSource(
          project.version
        )
    });

    return {
      ...project,
      sources,
      allowUnsafe:
        /<AllowUnsafeBlocks>\s*true\s*<\/AllowUnsafeBlocks>/i
          .test(projectXml),
      checkOverflow:
        /<CheckForOverflowUnderflow>\s*true\s*<\/CheckForOverflowUnderflow>/i
          .test(projectXml),
      deterministic:
        !/<Deterministic>\s*false\s*<\/Deterministic>/i
          .test(projectXml),
      implicitUsings:
        !/<ImplicitUsings>\s*(?:false|disable)\s*<\/ImplicitUsings>/i
          .test(projectXml),
      nullable:
        !/<Nullable>\s*(?:false|disable)\s*<\/Nullable>/i
          .test(projectXml),
      optimize: true
    };
  }).filter(project =>
    project.sources.length > 0
  );
}

function browserCompilerReferenceFingerprint(
  referenceFiles =
    selectedBrowserCompilerReferences(),
  referenceRevision =
    browserCompilerReferenceRevision
) {
  return JSON.stringify({
    revision:
      Number(referenceRevision) || 0,
    files: referenceFiles.map(file => ({
      name: String(file.name || ""),
      size: Number(file.size) || 0,
      lastModified:
        Number(file.lastModified) || 0,
      path:
        browserCompilerReferencePath(file)
    }))
  });
}

function browserCompilationProjectFingerprint(
  projects
) {
  const sourceFiles = projects.flatMap(
    project => project.sources.map(source => ({
      name:
        `${project.id}/${source.name}`,
      content: source.content
    }))
  );
  const sourceFingerprint =
    window.RMLCompile?.fingerprint?.(
      sourceFiles
    ) || "unavailable";
  const projectOptions = projects.map(
    project => ({
      id: project.id,
      assemblyName: project.assemblyName,
      version: project.version,
      allowUnsafe: project.allowUnsafe,
      checkOverflow: project.checkOverflow,
      deterministic: project.deterministic,
      implicitUsings: project.implicitUsings,
      nullable: project.nullable,
      optimize: project.optimize
    })
  );

  return JSON.stringify({
    sourceFingerprint,
    projectOptions
  });
}

function browserCompilationFingerprint(
  projects,
  referenceFiles =
    selectedBrowserCompilerReferences(),
  referenceRevision =
    browserCompilerReferenceRevision
) {
  return JSON.stringify({
    project:
      browserCompilationProjectFingerprint(
        projects
      ),
    references:
      browserCompilerReferenceFingerprint(
        referenceFiles,
        referenceRevision
      )
  });
}

function formatBrowserCompilerDiagnostics(
  result
) {
  return (Array.isArray(result?.diagnostics)
    ? result.diagnostics
    : [])
    .filter(diagnostic =>
      String(
        diagnostic?.severity || window.RMLI18n.t("ui.auto.c61dcc959d06")
      ).toLowerCase() === "error"
    )
    .slice(0, 12)
    .map(diagnostic => {
      const line =
        Number(diagnostic?.startLine) || 0;
      const column =
        Number(diagnostic?.startColumn) || 0;
      const location = line > 0
        ? `:${line}:${Math.max(1, column)}`
        : "";

      return `Generated C#: ${diagnostic?.projectLabel || window.RMLI18n.t("ui.literal.3ab238d024c9")} · ${diagnostic?.fileName || window.RMLI18n.t("ui.literal.2d4e6341d5cd")}${location} ${diagnostic?.id || "C#"}: ${diagnostic?.message || "Compilation failed."}`;
    });
}

function compiledBrowserOutputFiles(
  result,
  outputs
) {
  const projects =
    Array.isArray(result.projects)
      ? result.projects
      : generatedProjectDescriptors(
          result
        );
  const baseName = String(
    projects.find(project =>
      project.id === "main-mod"
    )?.assemblyName ||
    projects[0]?.assemblyName ||
    generatedBaseName()
  );
  const root = result.multiProject
    ? safeArchiveSegment(
        `${baseName}-RML-Project`,
        window.RMLI18n.t("ui.literal.ede9859c0c93")
      )
    : "";
  const projectMap = new Map(
    projects.map(project => [
      project.id,
      project
    ])
  );

  return outputs.map(output => {
    const project =
      projectMap.get(output.projectId) ||
      projects[0];
    const assemblyName = safeArchiveSegment(
      output.assemblyName ||
      project?.assemblyName,
      window.RMLI18n.t("ui.literal.5aa36d8c50e4")
    );
    const target = [
      project?.folder || "",
      "bin/Release/net10.0",
      `${assemblyName}.dll`
    ].filter(Boolean).join("/");

    return {
      name: root
        ? `${root}/${target}`
        : target,
      content: output.peImage,
      type:
        "application/vnd.microsoft.portable-executable"
    };
  });
}

function browserCompiledPlaceholderArtifacts(
  catalog
) {
  const outputs = catalog.projects.map(
    project => ({
      projectId: project.id,
      assemblyName: project.assemblyName,
      peImage: new Uint8Array()
    })
  );

  return compiledBrowserOutputFiles(
    catalog,
    outputs
  ).map((file, index) => {
    const project = catalog.projects[index];
    const relativePath =
      stripGeneratedArchiveRoot(
        file.name,
        catalog.multiProject
      );

    return {
      key: `compiled:${project.id}`,
      archivePath: file.name,
      relativePath,
      fileName:
        relativePath.split("/").pop() ||
        relativePath,
      content: null,
      type: file.type,
      ...generatedArtifactKind(
        relativePath,
        file.type
      ),
      projectId: project.id,
      projectLabel: project.label,
      deployDirectory:
        project.deployDirectory,
      projectRole: project.role,
      requiresResonitePath: false,
      copyable: false
    };
  });
}

function invalidateBrowserCompilerBuild(
  resetReferences = false
) {
  browserCompilerBuildCache = null;

  if (resetReferences) {
    if (browserCompilerBuilding) {
      window.RMLCompile
        ?.cancelCompilation?.(
          "Compiler references changed."
        );
    } else {
      void window.RMLCSharp14Roslyn
        ?.resetCompilerReferences?.();
    }
  }
}

function retireBrowserCompilerBuildForProjectReplacement(
  message
) {
  browserCompilerAdditionalRequiredReferences
    .clear();
  browserCompilerReferenceRevision += 1;
  browserCompilerBuildCache = null;
  browserCompilerBuildFingerprint = "";

  if (browserCompilerBuilding) {
    window.RMLCompile
      ?.cancelCompilation?.(message);
  }
}

function updateBrowserCompilerStatus(
  completeCatalog
) {
  if (
    !elements.exportCompilerReferenceStatus ||
    !elements.exportCompilerBuildStatus
  ) {
    return {
      available: false,
      missing: []
    };
  }

  const references =
    selectedBrowserCompilerReferences();
  const missing =
    missingBrowserCompilerReferences(
      completeCatalog
    );
  const available =
    window.RMLCompile?.capabilities?.()
      ?.binaryCompilation === true;
  const projects =
    browserCompilationProjects(
      completeCatalog
    );
  const fingerprint =
    browserCompilationFingerprint(projects);
  const cacheReady =
    browserCompilerBuildCache
      ?.fingerprint === fingerprint;

  if (missing.length > 0) {
    elements.exportCompilerReferenceStatus.textContent =
      window.RMLI18n.format(
        missing.length === 1
          ? "export.compiler_references.missing.one"
          : "export.compiler_references.missing.other",
        { count: missing.length, dlls: missing.join(", ") }
      );
    elements.exportCompilerReferenceStatus.dataset.state =
      "missing";
  } else {
    elements.exportCompilerReferenceStatus.textContent =
      window.RMLI18n.format(
        references.length === 1
          ? "export.compiler_references.ready.one"
          : "export.compiler_references.ready.other",
        { count: references.length }
      );
    elements.exportCompilerReferenceStatus.dataset.state =
      "ready";
  }
  renderBrowserCompilerReferenceList();

  if (browserCompilerReferenceSearchRunning) {
    elements.exportCompilerBuildStatus.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.13b772bea046}}");
  } else if (!available) {
    elements.exportCompilerBuildStatus.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.ab68393968dd}}");
  } else if (browserCompilerBuilding) {
    elements.exportCompilerBuildStatus.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.19c59c5f8401}}");
  } else if (cacheReady) {
    elements.exportCompilerBuildStatus.textContent =
      `${browserCompilerBuildCache.outputs.length} DLL${browserCompilerBuildCache.outputs.length === 1 ? "" : "s"} ready for the ZIP.`;
  } else if (missing.length > 0) {
    elements.exportCompilerBuildStatus.textContent =
      browserCompilerDirectoryFileCount > 0
        ? `Folder checked: ${browserCompilerDirectoryFileCount.toLocaleString()} files · ${browserCompilerDirectoryMatchCount} required DLL${browserCompilerDirectoryMatchCount === 1 ? "" : "s"} found. Drop missing DLLs or another folder above.`
        : "";
  } else {
    elements.exportCompilerBuildStatus.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.9cb7a5a88476}}");
  }

  setExportControlAvailability(
    elements.exportClearCompilerReferences,
    (
      references.length > 0 ||
      browserCompilerDirectoryFiles.length > 0
    ) &&
      !browserCompilerBuilding
  );
  const pickerDisabled =
    browserCompilerBuilding ||
    browserCompilerReferenceSearchRunning;
  if (elements.exportCompilerDirectory) {
    elements.exportCompilerDirectory.disabled =
      pickerDisabled;
  }

  return {
    available,
    missing,
    cacheReady,
    fingerprint,
    projectCount: projects.length
  };
}

function browserCompilerBuildSuperseded(
  details
) {
  const error = new Error(
    `Compiler build superseded: ${String(
      details || "the compilation input changed"
    )}`
  );
  error.code =
    "RML_COMPILER_BUILD_SUPERSEDED";
  return error;
}

function assertBrowserCompilerSignal(signal) {
  if (signal?.aborted) {
    throw signal.reason ||
      exportDeliveryCancelled();
  }
}

async function compileGeneratedBrowserDlls(
  catalog = null,
  request = null,
  signal = null
) {
  assertBrowserCompilerSignal(signal);
  const completeCatalog = catalog ||
    freezeGeneratedArtifactCatalog(
      buildGeneratedArtifactCatalog(
        true,
        true
      )
    );
  const projects =
    browserCompilationProjects(
      completeCatalog
    );
  const projectEpoch = request?.projectEpoch ??
    projectApplicationEpoch;
  const initialReferenceFiles =
    selectedBrowserCompilerReferences();
  const initialFingerprint =
    browserCompilationFingerprint(
      projects,
      initialReferenceFiles
    );

  if (browserCompilerBuildPromise) {
    if (
      browserCompilerBuildProjectEpoch ===
        projectEpoch &&
      browserCompilerBuildFingerprint ===
        initialFingerprint &&
      browserCompilerBuildSignal === signal
    ) {
      return browserCompilerBuildPromise;
    }
    try {
      await browserCompilerBuildPromise;
    } catch {}
    assertBrowserCompilerSignal(signal);
    if (
      projectEpoch !== projectApplicationEpoch
    ) {
      throw browserCompilerBuildSuperseded(
        "the project was replaced"
      );
    }
    if (request) {
      assertExportRequestCurrent(
        request,
        true
      );
    }
    return compileGeneratedBrowserDlls(
      completeCatalog,
      request,
      signal
    );
  }

  if (
    browserCompilerBuildCache
      ?.fingerprint === initialFingerprint &&
    browserCompilerBuildCache
      ?.projectEpoch === projectEpoch
  ) {
    return browserCompilerBuildCache;
  }

  const missing =
    missingBrowserCompilerReferences(
      completeCatalog
    );
  if (missing.length > 0) {
    throw new Error(
      `Missing compiler reference DLLs: ${missing.join(", ")}`
    );
  }

  const compiler = window.RMLCompile;
  if (
    typeof compiler?.compile !== "function" ||
    compiler.capabilities?.()
      ?.binaryCompilation !== true
  ) {
    throw new Error(
      window.RMLI18n.t("js.presentation.ab68393968dd")
    );
  }

  browserCompilerBuilding = true;
  browserCompilerBuildFingerprint =
    initialFingerprint;
  browserCompilerBuildProjectEpoch =
    projectEpoch;
  browserCompilerBuildSignal = signal;
  updateExportDialog();

  const buildPromise = (async () => {
    let result = null;
    let compiledReferenceFiles =
      initialReferenceFiles;
    let compiledReferenceRevision =
      browserCompilerReferenceRevision;
    for (let attempt = 0; attempt < 8; attempt += 1) {
      assertBrowserCompilerSignal(signal);
      if (
        projectEpoch !== projectApplicationEpoch
      ) {
        throw browserCompilerBuildSuperseded(
          "the project was replaced"
        );
      }
      if (request) {
        assertExportRequestCurrent(
          request,
          true
        );
      }
      compiledReferenceFiles =
        selectedBrowserCompilerReferences();
      compiledReferenceRevision =
        browserCompilerReferenceRevision;
      result = await compiler.compile(
        projects.flatMap(project =>
          project.sources
        ),
        {
          projects,
          referenceFiles:
            compiledReferenceFiles,
          signal,
          emitPdb: false,
          onProgress(progress) {
            if (
              projectEpoch !==
                projectApplicationEpoch ||
              !elements.exportCompilerBuildStatus
            ) {
              return;
            }

            if (progress?.phase === "references") {
              elements.exportCompilerBuildStatus.textContent =
                `References ${progress.completed}/${progress.total}: ${progress.name}`;
            } else {
              elements.exportCompilerBuildStatus.textContent =
                `Building ${progress.completed}/${progress.total}: ${progress.name}`;
            }
          }
        }
      );

      assertBrowserCompilerSignal(signal);
      if (
        projectEpoch !== projectApplicationEpoch
      ) {
        throw browserCompilerBuildSuperseded(
          "the project was replaced"
        );
      }
      if (request) {
        assertExportRequestCurrent(
          request,
          true
        );
      }
      if (
        compiledReferenceRevision !==
          browserCompilerReferenceRevision ||
        browserCompilerReferenceFingerprint(
          compiledReferenceFiles,
          compiledReferenceRevision
        ) !==
          browserCompilerReferenceFingerprint()
      ) {
        throw browserCompilerBuildSuperseded(
          "the selected compiler references changed"
        );
      }

      if (result?.ok === true) break;

      const indirectMissing =
        missingAssembliesFromCompilerResult(result);
      if (indirectMissing.length === 0) break;

      for (const name of indirectMissing) {
        browserCompilerAdditionalRequiredReferences.set(
          normalizedAssemblyFileName(name),
          name
        );
      }

      setBrowserCompilerSearchStatus(
        `Finding ${indirectMissing.join(", ")}…`
      );
      const discovered =
        selectBrowserCompilerFiles(
          browserCompilerDirectoryFiles,
          indirectMissing,
          { invalidate: false }
        );
      browserCompilerDirectoryMatchCount +=
        discovered.files.length;
      if (
        discovered.files.length === 0 ||
        discovered.missing.length > 0
      ) {
        throw browserCompilerReferenceSelectionError(
          `Not found in the Resonite folder: ${discovered.missing.join(", ") || indirectMissing.join(", ")}. Drop the missing DLLs or another folder onto the Missing DLLs field.`
        );
      }
    }

    if (result?.ok !== true) {
      const diagnostics =
        formatBrowserCompilerDiagnostics(
          result
        );
      throw new Error(
        diagnostics.join("\n") ||
        result?.error ||
        window.RMLI18n.t("ui.literal.d4794a7f932b")
      );
    }

    const fingerprint =
      browserCompilationFingerprint(
        projects,
        compiledReferenceFiles,
        compiledReferenceRevision
      );
    const cache = Object.freeze({
      projectEpoch,
      fingerprint,
      outputs: result.outputs,
      diagnostics: result.diagnostics
    });

    browserCompilerBuildCache = cache;
    return cache;
  })();
  const trackedPromise =
    buildPromise.finally(() => {
      retainSelectedBrowserCompilerDirectoryFiles();
      if (
        browserCompilerBuildPromise ===
          trackedPromise
      ) {
        browserCompilerBuilding = false;
        browserCompilerBuildPromise = null;
        browserCompilerBuildFingerprint = "";
        browserCompilerBuildProjectEpoch = 0;
        browserCompilerBuildSignal = null;
        if (elements.exportDialog?.open) {
          updateExportDialog();
        }
      }
    });
  browserCompilerBuildPromise =
    trackedPromise;

  return browserCompilerBuildPromise;
}

function addBrowserCompilerReferenceFiles(
  fileList,
  {
    invalidate = true,
    refresh = true
  } = {}
) {
  let added = 0;
  for (const file of fileList || []) {
    if (!/\.dll$/i.test(file?.name || "")) {
      continue;
    }

    const key =
      String(file.name).toLowerCase();
    if (
      browserCompilerReferenceFiles.get(
        key
      ) === file
    ) {
      continue;
    }
    browserCompilerReferenceFiles.set(
      key,
      file
    );
    added += 1;
  }

  if (added > 0) {
    browserCompilerReferenceRevision += 1;
    if (invalidate) {
      invalidateBrowserCompilerBuild(true);
      const completeCatalog =
        buildGeneratedArtifactCatalog(
          true,
          true
        );
      updateExportPreviewStatus(
        completeCatalog.artifacts,
        getDiagnostics()
      );
    }
  }

  if (refresh) updateExportDialog();
  return added;
}

function clearBrowserCompilerReferences() {
  const changed =
    browserCompilerReferenceFiles.size > 0 ||
    browserCompilerAdditionalRequiredReferences
      .size > 0 ||
    browserCompilerDirectoryFiles.length > 0;
  browserCompilerReferenceFiles.clear();
  browserCompilerAdditionalRequiredReferences.clear();
  browserCompilerDirectoryFiles = Object.freeze([]);
  browserCompilerDirectoryFileCount = 0;
  browserCompilerDirectoryMatchCount = 0;
  browserCompilerReferencePaths = new WeakMap();
  if (changed) {
    browserCompilerReferenceRevision += 1;
  }
  invalidateBrowserCompilerBuild(true);
  updateExportDialog();
}

function renderExportProjectSummary(
  catalog
) {
  const host =
    elements.exportProjectSummary;

  if (!host) {
    return;
  }

  const fragment =
    document.createDocumentFragment();
  const projectPaths = new Set(
    catalog.artifacts
      .map(artifact => artifact.projectId)
  );

  for (const project of catalog.projects) {
    if (!projectPaths.has(project.id)) {
      continue;
    }

    const card =
      document.createElement("div");
    const title =
      document.createElement("strong");
    const detail =
      document.createElement("small");
    const target =
      document.createElement("b");

    card.className =
      "export-generated-project";
    title.textContent =
      project.label;
    detail.textContent =
      project.folder
        ? `${project.folder}/${project.assemblyName}.csproj`
        : `${project.assemblyName}.csproj`;
    target.textContent =
      `→ ${project.deployDirectory}`;

    card.append(
      title,
      detail,
      target
    );
    fragment.appendChild(card);
  }

  host.replaceChildren(fragment);
  host.hidden =
    host.childElementCount === 0;
}

function renderExportGeneratedFiles(
  catalog
) {
  const host =
    elements.exportGeneratedFiles;

  if (!host) {
    return;
  }

  if (catalog.artifacts.length === 0) {
    const empty =
      document.createElement("p");

    empty.className =
      "export-generated-empty";
    empty.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.a3e75bb14825}}");
    host.replaceChildren(empty);
    return;
  }

  const fragment =
    document.createDocumentFragment();

  for (const artifact of
    catalog.artifacts) {
    const row =
      document.createElement("button");
    const badge =
      document.createElement("span");
    const copy =
      document.createElement("span");
    const path =
      document.createElement("strong");
    const detail =
      document.createElement("small");
    const target =
      document.createElement("b");

    row.type = "button";
    row.className =
      "export-generated-file";
    row.dataset.kind = artifact.kind;
    row.dataset.artifactKey =
      artifact.key;
    row.title = artifact.copyable === false
      ? `${artifact.relativePath} is created by the browser compiler.`
      : `Select ${artifact.relativePath} for copying`;
    row.disabled =
      artifact.copyable === false;

    badge.className =
      "export-generated-file-badge";
    badge.textContent = artifact.badge;
    copy.className =
      "export-generated-file-copy";
    path.textContent =
      artifact.relativePath;
    detail.textContent = artifact.copyable === false
      ? `${artifact.kindLabel} · compiled locally · ${artifact.projectLabel}`
      : `${artifact.kindLabel} · ${artifact.projectLabel}`;
    copy.append(path, detail);

    target.className =
      "export-generated-file-target";
    target.textContent =
      artifact.deployDirectory
        ? artifact.deployDirectory
        : "support";

    row.append(
      badge,
      copy,
      target
    );
    if (artifact.copyable !== false) {
      row.addEventListener(
        "click",
        () => {
          exportCopyArtifactKey =
            artifact.key;

          updateExportCopyButtonState(
            catalog
          );
        }
      );
    }
    fragment.appendChild(row);
  }

  host.replaceChildren(fragment);
}

function currentExportCopyArtifact(
  existingCatalog = null
) {
  const catalog =
    existingCatalog ||
    buildGeneratedArtifactCatalog(
      true,
      true
    );
  let artifact = catalog.artifacts.find(
    candidate =>
      candidate.copyable !== false &&
      candidate.key ===
        exportCopyArtifactKey
  );

  if (!artifact) {
    const graphFiles =
      getAdditionalGeneratedSourceFiles();

    artifact =
      preferredGraphArtifact(
        catalog.artifacts.filter(candidate =>
          candidate.copyable !== false
        ),
        graphFiles
      ) ||
      catalog.artifacts.find(candidate =>
        candidate.copyable !== false
      ) ||
      null;
  }

  exportCopyArtifactKey =
    artifact?.key || "";

  return {
    catalog,
    artifact
  };
}

function updateExportCopyButtonState(
  existingCatalog = null,
  existingPathAvailable = null,
  existingHasDiagnostics = null
) {
  const { artifact } =
    currentExportCopyArtifact(
      existingCatalog
    );
  const pathAvailable =
    existingPathAvailable === null
      ? Boolean(
          elements.exportResonitePath
            ?.value.trim()
        )
      : existingPathAvailable;
  const hasDiagnostics =
    existingHasDiagnostics === null
      ? getDiagnostics().length > 0
      : existingHasDiagnostics;
  const exportReady =
    !hasDiagnostics && !exportPreflightRequest && !exportDeliveryBusy;

  elements.exportGeneratedFiles
    ?.querySelectorAll(
      ".export-generated-file"
    )
    .forEach(row => {
      const selected =
        row.dataset.artifactKey ===
          artifact?.key;

      row.classList.toggle(
        "selected",
        selected
      );

      row.setAttribute(
        "aria-pressed",
        String(selected)
      );
    });

  if (elements.exportCopySelectedFile) {
    const unavailable =
      !exportReady ||
      !artifact ||
      artifact.copyable === false ||
      (
        artifact.requiresResonitePath &&
        !pathAvailable
      );
    setExportControlAvailability(
      elements.exportCopySelectedFile,
      !unavailable
    );
    elements.exportCopySelectedFile.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.af74f7c5362a}}");
    elements.exportCopySelectedFile.title =
      artifact
        ? artifact.relativePath
        : window.RMLI18n.t("ui.literal.20d50b2f5695");
  }
}

function setExportValidationFailure(error) {
  const message = error instanceof Error ? error.message : String(error);
  setExportReadiness(
    "error",
    {
      fingerprint:
        exportReadiness.fingerprint,
      diagnostics: [
        [
          "Generated C#:",
          window.RMLI18n.t("ui.literal.b4580a3d5f8d")
        ].some(prefix => message.startsWith(prefix))
          ? message
          : `Generated C#: ${message}`
      ],
      fileCount:
        exportReadiness.fileCount
    }
  );
  setExportControlAvailability(
    elements.exportDownloadSelected,
    false
  );
  setExportControlAvailability(
    elements.exportCopySelectedFile,
    false
  );
  elements.exportDownloadHint.textContent = message;
  elements.exportDownloadHint.classList.add("error");
}

async function copySelectedExportArtifact(button) {
  if (exportPreflightRequest || exportDeliveryBusy || !exportControlAvailable(button)) return;
  const selectedKey = exportCopyArtifactKey;
  const job = beginExportDelivery();
  try {
    const checked = await awaitExportDelivery(
      job,
      requestExportPreflight()
    );
    assertExportDeliveryCurrent(job);
    assertExportRequestCurrent(checked.request, true);
    const artifact = checked.artifacts.find(
      candidate =>
        candidate.copyable !== false &&
        candidate.key === selectedKey
    );
    if (!artifact) throw new Error(window.RMLI18n.t("ui.literal.6513029b18f3"));
    exportCopyArtifactKey = selectedKey;
    await awaitExportDelivery(
      job,
      copyText(artifact.content, button)
    );
  } catch (error) {
    if (!expectedExportCancellation(error)) {
      setExportValidationFailure(error);
    }
  } finally {
    if (finishExportDelivery(job)) {
      applyPrimaryExportAvailability([]);
      if (elements.exportDialog?.open) {
        updateExportDialog();
      }
    }
  }
}

function currentApiExportCompatibilityWarning() {
  const graph =
    state.extensions
      ?.typedNodeGraph;

  if (
    !graph ||
    !graph.configSnapshot ||
    !Array.isArray(
      graph.configSnapshot.nodes
    ) ||
    !Array.isArray(graph.nodes)
  ) {
    return null;
  }

  const apiNodes =
    graph.nodes.filter(node =>
      node?.kind === "operator" &&
      String(
        node.operatorId || ""
      ).startsWith("api.")
    );

  if (apiNodes.length === 0) {
    return null;
  }

  const report =
    window.RMLApiNodeFactoryReport;
  const definitions =
    window.RMLModNodeRegistry
      ?.getNodeDefinitions?.() || {};
  const liveFactoryVerified =
    Boolean(
      report &&
      typeof report === "object" &&
      report.liveCatalogVerified ===
        true &&
      report.catalogSource ===
        "scanner" &&
      report.verificationPassed ===
        true
    );
  const contractsVerified =
    liveFactoryVerified &&
    apiNodes.every(node => {
      const definition =
        definitions[
          node.operatorId
        ];
      const contract =
        definition?.apiVerification;

      return Boolean(
        definition
          ?.catalogGenerated === true &&
        contract &&
        typeof contract === "object" &&
        String(contract.nodeId || "") ===
          String(node.operatorId) &&
        String(
          contract.catalogFingerprint ||
          ""
        ) ===
          String(
            report.catalogFingerprint ||
            ""
          ) &&
        String(
          contract.engineVersion || ""
        ) ===
          String(
            report.engineVersion || ""
          ) &&
        String(
          contract.contractFingerprint ||
          ""
        ).trim()
      );
    });

  if (contractsVerified) {
    return null;
  }

  return Object.freeze({
    apiNodeCount:
      apiNodes.length,
    catalogSource:
      String(
        report?.catalogSource ||
        "unavailable"
      )
  });
}

function renderExportApiCompatibilityWarning() {
  const host =
    elements.exportApiCompatibilityWarning;
  const message =
    elements.exportApiCompatibilityWarningMessage;

  if (!host || !message) {
    return;
  }

  const warning =
    currentApiExportCompatibilityWarning();

  host.hidden = !warning;

  if (!warning) {
    message.textContent = "";
    return;
  }

  const warningKey =
    warning.apiNodeCount === 1
      ? "export.api_compatibility_warning.one"
      : "export.api_compatibility_warning.other";

  message.textContent = window.RMLI18n.format(warningKey, {
    count: warning.apiNodeCount.toLocaleString()
  });
}

function updateExportDialog() {
  setExportControlAvailability(
    elements.exportCopySelectedFile,
    false
  );
  setExportControlAvailability(
    elements.exportDownloadSelected,
    false
  );
  const guidanceStatus = generatedGuidanceStatus();
  if (guidanceStatus) {
    elements.exportPackageSummary.textContent = guidanceStatus;
    elements.exportPackageMode.textContent = window.RMLI18n.t("{{i18n:js.presentation.2b50ff807d04}}");
    elements.exportProjectSummary.replaceChildren();
    elements.exportGeneratedFiles.textContent = guidanceStatus;
    return;
  }
  elements.exportDownloadHint.classList.remove("error");
  const platform =
    elements.exportPlatform.value;
  const includeCs =
    elements.exportIncludeCs.checked;
  const includeCsproj =
    elements.exportIncludeCsproj.checked;
  const includeCompiled =
    elements.exportIncludeCompiled.checked;
  if (elements.exportCompilerDetails) {
    elements.exportCompilerDetails.hidden =
      !includeCompiled;
  }
  const catalog =
    buildGeneratedArtifactCatalog(
      includeCs,
      includeCsproj
    );
  const completeCatalog =
    buildGeneratedArtifactCatalog(
      true,
      true
    );
  const compiledArtifacts = includeCompiled
    ? browserCompiledPlaceholderArtifacts(
        completeCatalog
      )
    : [];
  const displayCatalog = {
    ...catalog,
    projects: completeCatalog.projects,
    artifacts: [
      ...catalog.artifacts,
      ...compiledArtifacts
    ]
  };
  const pathAvailable =
    elements.exportResonitePath.value
      .trim()
      .length > 0;
  const hasSelection =
    displayCatalog.artifacts.length > 0;
  const projectPathMissing =
    includeCsproj &&
    !pathAvailable;
  const hasDiagnostics =
    getDiagnostics().length > 0;
  const exportReady =
    !hasDiagnostics && !exportPreflightRequest && !exportDeliveryBusy;
  const compilerStatus =
    updateBrowserCompilerStatus(
      completeCatalog
    );
  const compilerBlocked =
    includeCompiled &&
    (
      !compilerStatus.available ||
      browserCompilerBuilding ||
      browserCompilerReferenceSearchRunning
    );
  const sourceCount =
    completeCatalog.artifacts.filter(
      artifact =>
        artifact.kind === "source"
    ).length;
  const projectBuildCount =
    completeCatalog.artifacts.filter(
      artifact =>
        artifact.kind !== "source"
    ).length;
  const activeProjectIds = new Set(
    displayCatalog.artifacts
      .map(artifact => artifact.projectId)
      .filter(projectId =>
        projectId !== "support"
      )
  );
  const activeProjectCount =
    activeProjectIds.size;
  const effectiveMultiProject =
    activeProjectCount > 1;

  renderExportApiCompatibilityWarning();

  elements.exportCsFilename.textContent =
    `${sourceCount} generated source file${
      sourceCount === 1 ? "" : "s"
    }`;
  elements.exportCsprojFilename.textContent =
    `${projectBuildCount} project/build/support file${
      projectBuildCount === 1
        ? ""
        : "s"
    }`;

  if (elements.exportPackageSummary) {
    elements.exportPackageSummary.textContent =
      `${activeProjectCount} project${activeProjectCount === 1 ? "" : "s"} · ${displayCatalog.artifacts.length} file${displayCatalog.artifacts.length === 1 ? "" : "s"}`;
  }

  if (elements.exportPackageMode) {
    elements.exportPackageMode.textContent =
      displayCatalog.artifacts.length === 0
        ? window.RMLI18n.t("ui.literal.a8fcece9d93a")
        : effectiveMultiProject
          ? window.RMLI18n.t("ui.literal.120602fc10d2")
          : window.RMLI18n.t("index.text.9d3ad1a06503");
    elements.exportPackageMode.dataset.mode =
      effectiveMultiProject
        ? "multi"
        : "single";
  }

  renderExportProjectSummary(displayCatalog);
  renderExportGeneratedFiles(displayCatalog);
  updateExportCopyButtonState(
    displayCatalog,
    pathAvailable,
    hasDiagnostics
  );

  elements.exportResonitePath.setAttribute(
    "aria-invalid",
    String(projectPathMissing)
  );
  setExportControlAvailability(
    elements.exportDownloadSelected,
    exportReady &&
      hasSelection &&
      !projectPathMissing &&
      !compilerBlocked
  );

  const platformNotes = {
    windows:
      window.RMLI18n.t("ui.auto.42b6d7810a6b"),
    linux:
      window.RMLI18n.t("ui.auto.def8dd33ae0b"),
    "linux-flatpak":
      window.RMLI18n.t("ui.auto.133b130c8499"),
    macos:
      window.RMLI18n.t("ui.auto.c90d391a53e6"),
    custom:
      window.RMLI18n.t("ui.auto.27a195a8939b")
  };

  elements.exportCompatibilityHint.innerHTML =
    platformNotes[platform] ||
    platformNotes.custom;

  if (exportReadiness.phase === "error" && exportReadiness.diagnostics.length) {
    elements.exportDownloadHint.textContent = exportReadiness.diagnostics.join("\n");
    elements.exportDownloadHint.classList.add("error");
    return;
  }

  if (!hasSelection) {
    elements.exportDownloadSelected.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.a479c9c34e87}}");
    elements.exportDownloadHint.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.d4342f6c8bb7}}");
    return;
  }

  if (includeCompiled) {
    elements.exportDownloadSelected.textContent =
      compilerStatus.cacheReady
        ? window.RMLI18n.t("js.presentation.7bd0e4b0ebc2")
        : window.RMLI18n.t("ui.literal.c9caa7143a49");
    elements.exportDownloadHint.textContent =
      compilerStatus.missing.length > 0
        ? browserCompilerDirectoryFileCount > 0
          ? window.RMLI18n.format("export.compiler_references.still_missing", {
              dlls: compilerStatus.missing.join(", ")
            })
          : window.RMLI18n.format("export.compiler_references.search_missing", {
              dlls: compilerStatus.missing.join(", ")
            })
        : browserCompilerBuilding
          ? window.RMLI18n.t("ui.literal.7dd3200524ef")
          : window.RMLI18n.format(
              compiledArtifacts.length === 1
                ? "export.compiler_references.manifest.one"
                : "export.compiler_references.manifest.other",
              { count: compiledArtifacts.length }
            );
    return;
  }

  if (effectiveMultiProject) {
    const destinations = [
      ...new Set(
        catalog.projects
          .filter(project =>
            catalog.artifacts.some(
              artifact =>
                artifact.projectId ===
                project.id
            )
          )
          .map(project =>
            project.deployDirectory
          )
      )
    ];

    elements.exportDownloadSelected.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.7bd0e4b0ebc2}}");
    elements.exportDownloadHint.textContent =
      `The live manifest above is the exact ZIP content: ${displayCatalog.artifacts.length} files across ${activeProjectCount} independently compiled projects${destinations.length > 0 ? `, deploying to ${destinations.join(" and ")}` : ""}.`;
    return;
  }

  if (catalog.artifacts.length === 1) {
    const artifact =
      catalog.artifacts[0];
    elements.exportDownloadSelected.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.a479c9c34e87}}");
    elements.exportDownloadHint.textContent =
      artifact.requiresResonitePath &&
      !pathAvailable
        ? window.RMLI18n.t("ui.literal.ecb08c4d0add")
        : `${artifact.relativePath} will be downloaded directly.`;
    return;
  }

  elements.exportDownloadSelected.textContent =
    window.RMLI18n.t("{{i18n:js.presentation.7bd0e4b0ebc2}}");
  elements.exportDownloadHint.textContent =
    `The live manifest above contains the exact ${catalog.artifacts.length} files that will be bundled into the ZIP.`;
}

function syncExportOptions() {
  state.exportOptions = {
    platform:
      elements.exportPlatform.value,
    resonitePath:
      elements.exportResonitePath.value,
    includeCs:
      elements.exportIncludeCs.checked,
    includeCsproj:
      elements.exportIncludeCsproj.checked,
    includeCompiled:
      elements.exportIncludeCompiled.checked
  };
  updateBuilderPreferences({
    exportOptions:
      state.exportOptions
  });
  persist();
  updateExportDialog();
}

function applyExportPlatformPreset() {
  const presetPath =
    EXPORT_PLATFORM_PRESETS[
      elements.exportPlatform.value
    ];

  if (presetPath) {
    elements.exportResonitePath.value =
      presetPath;
  }

  syncExportOptions();
}

function syncEditedResonitePath() {
  const selectedPlatform =
    elements.exportPlatform.value;
  const presetPath =
    EXPORT_PLATFORM_PRESETS[
      selectedPlatform
    ];

  if (
    presetPath &&
    normalizedResonitePath(
      elements.exportResonitePath.value
    ) !==
      normalizedResonitePath(
        presetPath
      )
  ) {
    elements.exportPlatform.value =
      "custom";
  }

  syncExportOptions();
}

let exportDialogOpenSequence = 0;

function openExportDialog() {
  if (exportDialogOpenPromise) return exportDialogOpenPromise;
  if (exportPreflightRequest || exportDeliveryBusy) return Promise.resolve(false);
  const sequence = ++exportDialogOpenSequence;
  exportDialogOpenPromise = (async () => {
    try {
      const checked = await requestExportPreflight({ prepareStyles: true });
      if (sequence !== exportDialogOpenSequence) return false;
      assertExportRequestCurrent(checked.request, true);
      elements.exportPlatform.value = state.exportOptions.platform || inferExportPlatform(state.exportOptions.resonitePath);
      elements.exportResonitePath.value = state.exportOptions.resonitePath;
      elements.exportIncludeCs.checked = Boolean(state.exportOptions.includeCs);
      elements.exportIncludeCsproj.checked = Boolean(state.exportOptions.includeCsproj);
      elements.exportIncludeCompiled.checked = Boolean(state.exportOptions.includeCompiled);
      updateExportDialog();
      ensureUniversalCustomSelect(elements.exportPlatform)?.refresh?.();
      elements.exportDialog.classList.remove("rml-dialog-loading");
      if (typeof elements.exportDialog.showModal === "function") elements.exportDialog.showModal();
      else elements.exportDialog.setAttribute("open", "");
      stabilizeDialogFocus(elements.exportDialog);
      requestAnimationFrame(() => {
        if (sequence === exportDialogOpenSequence && elements.exportDialog.open) {
          updateAdaptiveUtilityDialog(elements.exportDialog);
        }
      });
      return true;
    } catch (error) {
      if (
        sequence === exportDialogOpenSequence &&
        !expectedExportCancellation(error)
      ) {
        void showExportPreparationFailure(error);
      }
      return false;
    }
  })().finally(() => { exportDialogOpenPromise = null; });
  return exportDialogOpenPromise;
}

function closeExportDialog() {
  exportDialogOpenSequence += 1;
  cancelExportPreflight();
  cancelExportDelivery();
  elements.exportDialog.classList.remove(
    "mobile-full-modal",
    "rml-dialog-loading"
  );

  if (typeof elements.exportDialog.close === "function") {
    elements.exportDialog.close();
  } else {
    elements.exportDialog.removeAttribute("open");
  }
}

async function downloadSelectedExport() {
  if (exportPreflightRequest || exportDeliveryBusy || !exportControlAvailable(elements.exportDownloadSelected)) return;
  syncExportOptions();
  const job = beginExportDelivery();
  const originalLabel =
    elements.exportDownloadSelected.textContent;
  let resolvingReferences = false;
  try {
    const checked = await awaitExportDelivery(
      job,
      requestExportPreflight()
    );
    assertExportDeliveryCurrent(job);
    assertExportRequestCurrent(checked.request, true);
    const completeCatalog = checked.catalog;
    const includeCs =
      state.exportOptions.includeCs === true;
    const includeCsproj =
      state.exportOptions.includeCsproj === true;
    const includeCompiled =
      state.exportOptions.includeCompiled === true;
    const baseName = String(
      completeCatalog.projects.find(project =>
        project.id === "main-mod"
      )?.assemblyName ||
      completeCatalog.projects[0]
        ?.assemblyName ||
      generatedBaseName()
    );

    setExportControlAvailability(
      elements.exportDownloadSelected,
      false
    );
    elements.exportDownloadSelected.textContent =
      window.RMLI18n.t("{{i18n:js.presentation.820d6004b037}}");
    elements.exportDownloadHint.classList.remove("error");

    if (includeCompiled) {
      resolvingReferences = true;
      elements.exportDownloadSelected.textContent =
        window.RMLI18n.t("{{i18n:js.presentation.30ee6a1d77ea}}");
      await awaitExportDelivery(
        job,
        ensureBrowserCompilerReferences(
          completeCatalog,
          checked.request,
          job.controller.signal
        )
      );
      assertExportDeliveryCurrent(job);
      assertExportRequestCurrent(checked.request, true);
      resolvingReferences = false;
      elements.exportDownloadSelected.textContent =
        window.RMLI18n.t("{{i18n:js.presentation.820d6004b037}}");
    }
    assertExportDeliveryCurrent(job);
    assertExportRequestCurrent(checked.request, true);
    const result = selectedExportFilesFromCatalog(
      completeCatalog,
      includeCs,
      includeCsproj
    );
    if (includeCompiled) {
      elements.exportDownloadSelected.textContent =
        window.RMLI18n.t("{{i18n:js.presentation.7cc766ce5323}}");
      const compiled = await awaitExportDelivery(
        job,
        compileGeneratedBrowserDlls(
          completeCatalog,
          checked.request,
          job.controller.signal
        )
      );
      assertExportDeliveryCurrent(job);
      assertExportRequestCurrent(checked.request, true);
      result.files.push(
        ...compiledBrowserOutputFiles(
          completeCatalog,
          compiled.outputs
        )
      );
    }
    assertExportDeliveryCurrent(job);
    assertExportRequestCurrent(
      checked.request,
      true
    );
    const files = result.files;

    if (files.length === 0) {
      return;
    }

    if (
      files.length === 1 &&
      !result.multiProject &&
      !includeCompiled
    ) {
      const file = files[0];
      downloadBlob(
        new Blob(
          [file.content],
          {
            type:
              file.type ||
              "text/plain;charset=utf-8"
          }
        ),
        file.name
      );
      return;
    }

    downloadBlob(
      createZipBlob(files),
      `${baseName}-RML-Project.zip`
    );
  } catch (error) {
    if (expectedExportCancellation(error)) {
      setExportReadiness(
        "idle",
        {},
        getDiagnostics()
      );
    } else if (
      resolvingReferences ||
      error?.code ===
        "RML_COMPILER_REFERENCES_REQUIRED"
    ) {
      elements.exportDownloadHint.textContent =
        error instanceof Error
          ? error.message
          : String(error);
      elements.exportDownloadHint.classList.add(
        "error"
      );
    } else {
      setExportValidationFailure(error);
    }
  } finally {
    if (finishExportDelivery(job)) {
      elements.exportDownloadSelected.textContent =
        originalLabel;
      applyPrimaryExportAvailability([]);
      if (elements.exportDialog?.open) {
        updateExportDialog();
      }
    }
  }
}
