async function newBlank() {
  const previousProjectId =
    state.projectId;
  const retainedPreferences =
    synchronizeBuilderPreferencesFromState();

  if (builderHasActiveProject()) {
    closeProjectDialog();
    await paintBuilderUi();

    const confirmed =
      await confirmBuilderAction({
        tone: "danger",
        kicker: window.RMLI18n.t("ui.auto.e2f0669cd54e"),
        title: window.RMLI18n.t("ui.auto.4378ea2fc7c1"),
        message:
          window.RMLI18n.t("ui.auto.405f6ac1b9a6"),
        details:
          window.RMLI18n.t("ui.literal.f371fbf7d8c1"),
        confirmLabel: window.RMLI18n.t("ui.literal.c21571ac8339")
      });

    if (!confirmed) {
      openProjectDialog();
      setProjectFileStatus(
        window.RMLI18n.t("ui.literal.d39bea448b56")
      );
      return;
    }
  } else {
    closeProjectDialog();
  }

  const workSession = beginBuilderWork({
    kicker: window.RMLI18n.t("ui.auto.e2f0669cd54e"),
    title: window.RMLI18n.t("ui.auto.3e2a8d206052"),
    message:
      window.RMLI18n.t("ui.auto.05df0aad1e53"),
    detail:
      window.RMLI18n.t("ui.literal.38f1eca0ece5"),
    progress: 35
  });

  try {
    await paintBuilderUi();

    if (
      document.body.classList.contains(
        "rml-node-graph-mode"
      )
    ) {
      const packButton =
        document.getElementById(
          "pack-into-node"
        ) ||
        document.querySelector(
          ".rml-pack-button"
        );

      packButton?.click();
    }

    const newProjectId = createFreshProjectId();
    notifyProjectReplacement({ projectId: newProjectId }, "new-blank");
    state.metadata = {
      ...DEFAULT_METADATA,
      includeGuide:
        retainedPreferences.includeGuide
    };
    state.projectId = newProjectId;
    state.exportOptions = {
      ...retainedPreferences
        .exportOptions
    };
    state.extensions = {};
    state.activePage =
      "configuration-outline";
    state.nodes = [];
    state.selectedId = null;
    state.activeContainerId = ROOT_CONTAINER;
    state.collapsedPaletteGroups = [
      ...retainedPreferences
        .collapsedPaletteGroups
    ];
    writePageStateMarker(
      state.activePage,
      "new-blank"
    );
    renderMetadata();
    renderPalette();

    updateBuilderWork(
      workSession,
      {
        title: window.RMLI18n.t("ui.auto.57c113340d1d"),
        message:
          window.RMLI18n.t("ui.auto.eb4d040f102f"),
        progress: 75
      }
    );
    await paintBuilderUi();
    renderAll();

    await commitSuccessfulProjectStorage(
      previousProjectId,
      "new-blank"
    );

    updateBuilderWork(
      workSession,
      {
        title: window.RMLI18n.t("ui.auto.75fc43939579"),
        message:
          window.RMLI18n.t("ui.auto.5ce62cbacf2f"),
        progress: 100
      }
    );
    await paintBuilderUi();
  } finally {
    finishBuilderWork(workSession);
  }
}

