  document.addEventListener(
    "keydown",
    event => {
      if (event.key !== window.RMLI18n.t("ui.literal.b4cfe1f435f0")) {
        return;
      }

      const dragIsActive =
        dragScrollActive ||
        nodePointerDragActive ||
        palettePointerDragActive ||
        optionPointerDragActive ||
        Boolean(activeDraggedNodeId) ||
        Boolean(activeDraggedOptionId);

      if (!dragIsActive) {
        return;
      }

      event.preventDefault();
      event.stopImmediatePropagation();

      const restoreX =
        dragScrollOriginX;

      const restoreY =
        dragScrollOriginY;

      if (nodePointerDragActive) {
        finishNodePointerDrag(false);
      }
      else if (palettePointerDragActive) {
        finishPalettePointerDrag(false);
      }
      else if (optionPointerDragActive) {
        finishOptionPointerDrag(false);
      }
      else {
        finishDragInteraction();
      }

      clearPendingNodePointerDrag();
      clearPendingOptionPointerDrag();
      clearPendingPalettePointerDrag();

      window.scrollTo({
        left: restoreX,
        top: restoreY,
        behavior: "auto"
      });

      requestAnimationFrame(() => {
        window.scrollTo({
          left: restoreX,
          top: restoreY,
          behavior: "auto"
        });
      });
    },
    {
      capture: true
    }
  );

  document.addEventListener(
    "wheel",
    event => {
      const rawDominantWheelDelta =
        Math.abs(event.deltaX) >
        Math.abs(event.deltaY)
          ? event.deltaX
          : event.deltaY;

      const wheelDeltaScale =
        event.deltaMode === 1
          ? 16
          : event.deltaMode === 2
            ? Math.max(
                1,
                window.innerHeight ||
                  document.documentElement.clientHeight
              )
            : 1;

      const dominantWheelDelta =
        rawDominantWheelDelta *
        wheelDeltaScale;

      const direction =
        Math.sign(dominantWheelDelta);

      if (direction === 0) {
        return;
      }

      const nodeInsertDragActive =
        (
          nodePointerDragActive &&
          activeDraggedNodeId
        ) ||
        (
          palettePointerDragActive &&
          palettePointerPayload
        );

      if (nodeInsertDragActive) {
        event.preventDefault();
        event.stopImmediatePropagation();

        const heldNodeWheelScrollScope =
          nodeWheelScrollScopeActive(
            event.clientX,
            event.clientY
          );

        if (heldNodeWheelScrollScope) {
          nodeWheelTargetHost =
            nodeWheelScrollScopeHost;
          nodeWheelTargetContainerId =
            nodeWheelScrollScopeContainerId;
        } else {
          const liveNodeWheelTarget =
            nodeDropTargetAtPointer(
              event.clientX,
              event.clientY,
              nodePointerDragActive
                ? activeDraggedNodeId
                : null
            );

          if (
            !liveNodeWheelTarget ||
            !(liveNodeWheelTarget.host instanceof HTMLElement) ||
            !liveNodeWheelTarget.host.isConnected ||
            !liveNodeWheelTarget.containerId
          ) {
            nodeWheelDelta = 0;
            nodeWheelDirection = 0;
            return;
          }

          setNodePointerTarget(
            liveNodeWheelTarget.containerId,
            liveNodeWheelTarget.host,
            liveNodeWheelTarget.insertionIndex,
            event.clientX,
            event.clientY
          );

          if (
            !lockNodeWheelScrollScope(
              liveNodeWheelTarget.host,
              liveNodeWheelTarget.containerId,
              event.clientX,
              event.clientY
            )
          ) {
            nodeWheelDelta = 0;
            nodeWheelDirection = 0;
            return;
          }

          nodeWheelTargetHost =
            liveNodeWheelTarget.host;
          nodeWheelTargetContainerId =
            liveNodeWheelTarget.containerId;
        }

        if (
          !(nodeWheelTargetHost instanceof HTMLElement) ||
          !nodeWheelTargetHost.isConnected ||
          !nodeWheelTargetContainerId
        ) {
          nodeWheelDelta = 0;
          nodeWheelDirection = 0;
          return;
        }

        if (
          nodeWheelDirection !== 0 &&
          nodeWheelDirection !== direction
        ) {
          nodeWheelDelta = 0;
        }

        nodeWheelDirection = direction;

        nodeWheelDelta +=
          dominantWheelDelta;

        if (
          Math.abs(nodeWheelDelta) < 30
        ) {
          return;
        }

        nodeWheelDelta = 0;
        nodeWheelDirection = 0;
        stepNodeInsertWithWheel(direction);
        requestDragPlaceholderVisibility();
        return;
      }

      if (
        optionPointerDragActive &&
        activeDraggedOptionId &&
        activeDraggedOptionControllerId
      ) {
        if (
          optionWheelTargetHost &&
          optionWheelTargetHost.isConnected &&
          optionWheelTargetControllerId
        ) {
          event.preventDefault();
          event.stopImmediatePropagation();

          optionWheelDelta +=
            dominantWheelDelta;

          if (
            Math.abs(optionWheelDelta) < 30
          ) {
            return;
          }

          optionWheelDelta = 0;

          stepOptionInsertWithWheel(
            optionWheelTargetControllerId,
            optionWheelTargetHost,
            direction
          );

          requestDragPlaceholderVisibility();
          return;
        }

        if (
          optionContainerWheelTargetHost &&
          optionContainerWheelTargetHost.isConnected &&
          optionContainerWheelTargetContainerId
        ) {
          event.preventDefault();
          event.stopImmediatePropagation();

          optionContainerWheelDelta +=
            dominantWheelDelta;

          if (
            Math.abs(
              optionContainerWheelDelta
            ) < 30
          ) {
            return;
          }

          optionContainerWheelDelta = 0;

          stepOptionContainerInsertWithWheel(
            direction
          );

          requestDragPlaceholderVisibility();
        }
      }
    },
    {
      capture: true,
      passive: false
    }
  );

