function rmlRuntimeDisplayTransformGeneratedResult(
  result
) {
  if (typeof result === "string") {
    return rmlRuntimeDisplayInjectCSharp(
      result
    );
  }

  if (
    result &&
    typeof result === "object"
  ) {
    if (
      typeof result.source === "string"
    ) {
      result.source =
        rmlRuntimeDisplayInjectCSharp(
          result.source
        );
    }

    if (
      Array.isArray(result.files)
    ) {
      for (const file of result.files) {
        if (
          file &&
          typeof file.content === "string" &&
          /\.cs$/i.test(
            String(
              file.name ||
              file.path ||
              ""
            )
          ) &&
          file.content.includes(
            "public override void OnEngineInit"
          )
        ) {
          file.content =
            rmlRuntimeDisplayInjectCSharp(
              file.content
            );
        }
      }
    }

    if (result.files instanceof Map) {
      for (const [key, value] of
        result.files) {
        if (
          typeof value === "string" &&
          /\.cs$/i.test(
            String(key)
          ) &&
          value.includes(
            "public override void OnEngineInit"
          )
        ) {
          result.files.set(
            key,
            rmlRuntimeDisplayInjectCSharp(
              value
            )
          );
        }
      }
    }
  }

  return result;
}

const rmlRuntimeDisplayBaseMainGenerator =
  generateCode;

generateCode =
  function (...args) {
    const originalNodes =
      state.nodes;

    state.nodes =
      (function filter(nodes) {
        return (
          Array.isArray(nodes)
            ? nodes
            : []
        )
          .filter(node =>
            !rmlRuntimeDisplayIsNode(
              node
            )
          )
          .map(node => {
            if (node?.kind === LAYOUT_ROW_KIND) {
              const sourceChildren =
                Array.isArray(node.children)
                  ? node.children
                  : [];
              const layoutContext = {
                row: node,
                children: sourceChildren,
                index: 0
              };

              return {
                ...node,
                layoutItemIds:
                  sourceChildren
                    .map(child =>
                      String(child?.id || "")
                    )
                    .filter(Boolean),
                layoutItemMetadata:
                  sourceChildren
                    .map(child => ({
                      id:
                        String(
                          child?.id || ""
                        ),
                      widthPercent:
                        effectiveInlineRowWidthPercent(
                          child,
                          layoutContext
                        ),
                      hideLabel:
                        child?.hideLabel === true
                    }))
                    .filter(item => item.id),
                children:
                  filter(
                    node.children
                  )
              };
            }

            if (node?.kind !== "controller") {
              return node;
            }

            return {
              ...node,
              options:
                (
                  Array.isArray(node.options)
                    ? node.options
                    : []
                ).map(option => ({
                  ...option,
                  children:
                    filter(
                      option.children
                    )
                }))
            };
          });
      })(originalNodes);

    let result;

    try {
      result =
        rmlRuntimeDisplayBaseMainGenerator
          .apply(
            this,
            args
          );
    } finally {
      state.nodes =
        originalNodes;
    }

    if (
      result &&
      typeof result.then ===
        "function"
    ) {
      return result.then(
        rmlRuntimeDisplayTransformGeneratedResult
      );
    }

    return rmlRuntimeDisplayTransformGeneratedResult(
      result
    );
  };

