let rmlRuntimeDisplayPreviewUnsubscribe =
  null;
let rmlRuntimeDisplayPreviewChannel =
  "";
let rmlRuntimeDisplayMenuInitializedChannel =
  "";

function rmlRuntimeDisplayReleasePreviewBridge() {
  try {
    rmlRuntimeDisplayPreviewUnsubscribe?.();
  } catch {
  }

  rmlRuntimeDisplayPreviewUnsubscribe =
    null;
  rmlRuntimeDisplayPreviewChannel =
    "";
  rmlRuntimeDisplayMenuInitializedChannel =
    "";
}

function rmlRuntimeDisplayPreviewText(
  record,
  fallback
) {
  if (!record) {
    return fallback;
  }

  if (
    record.valueKind === "sequence" &&
    Array.isArray(record.value)
  ) {
    return record.value.length > 0
      ? record.value
          .map(value =>
            typeof value === "object"
              ? value?.display ||
                JSON.stringify(value)
              : String(value)
          )
          .join("\n")
      : "[]";
  }

  if (
    record.valueKind === "map" &&
    record.value &&
    typeof record.value === "object" &&
    !Array.isArray(record.value)
  ) {
    const entries =
      Object.entries(record.value);

    return entries.length > 0
      ? entries
          .map(([key, value]) =>
            `${key}: ${
              typeof value === "object"
                ? value?.display ||
                  JSON.stringify(value)
                : String(value)
            }`
          )
          .join("\n")
      : "{}";
  }

  return String(
    record.display ??
    record.value ??
    (
      record.isNull
        ? "<null>"
        : fallback
    )
  );
}

function rmlRuntimeDisplayPreviewItems(
  value
) {
  const normalized =
    String(value ?? "")
      .replace(/\r\n?/g, "\n");

  const items =
    normalized.split("\n");

  return items.length > 0
    ? items
    : [""];
}

function rmlRuntimeDisplayPreviewCopyIcon() {
  return `
    <svg viewBox="0 0 24 24" aria-hidden="true"><use href="assets/rml-icons.svg?v=1.21.20-universal-presentation-dev419-runtime-color-fidelity-overlay-open#icon-copy"></use></svg>
  `;
}

function rmlPreviewDirectConfigurationDisplayRecord(channel, nodeId) {
  const graph = state?.extensions?.typedNodeGraph;
  if (!graph?.active || !Array.isArray(graph.connections) || !Array.isArray(graph.nodes)) {
    return null;
  }
  const configurationNodeIds = new Set(
    graph.nodes
      .filter(node => node?.kind === "configuration")
      .map(node => String(node.id || ""))
  );
  const expectedPort = `config-${String(nodeId || "")}`;
  const connection = graph.connections.find(item =>
    configurationNodeIds.has(String(item?.fromNode || "")) &&
    String(item?.fromPort || "") === expectedPort &&
    String(item?.toPort || "") === "value"
  );
  if (!connection) return null;
  const target = graph.nodes.find(node => String(node?.id || "") === String(connection.toNode || ""));
  if (target?.kind !== "operator" || target?.operatorId !== "resonite.displayValue") return null;
  return window.RMLRuntimeBridge?.getValue?.(channel, String(target.id || "")) || null;
}

function rmlPreviewConfigurationLiveRecord(channel, nodeId) {
  return window.RMLRuntimeBridge?.getValue?.(
    channel,
    `configuration:${String(nodeId || "")}`
  ) || rmlPreviewDirectConfigurationDisplayRecord(channel, nodeId);
}

function rmlRuntimeDisplaySyncConfigurationPreview(channel) {
  if (!settingsPreviewDraft || !window.RMLRuntimeBridge) {
    return false;
  }

  let changed = false;
  const changedNodeIds = [];
  const activeLiveNodeIds =
    new Set();
  const entries =
    typeof flattenNodes === "function"
      ? flattenNodes(state?.nodes || [])
      : [];

  for (const entry of entries) {
    const node = entry?.node;
    if (!node || node.kind === LAYOUT_ROW_KIND || node.valueType === "runtimeDisplay" || node.valueType === "button") {
      continue;
    }

    const record = rmlPreviewConfigurationLiveRecord(channel, node.id);
    if (!record) continue;

    activeLiveNodeIds.add(
      String(node.id)
    );

    let liveValue = record.value ?? record.display;
    if (
      node.dynamicSettingKind &&
      (record.value === undefined || record.value === null) &&
      String(record.display ?? "").trim() === "(None)"
    ) {
      liveValue = "";
    }
    window.__RMLPreviewTrace?.push?.({
      at: Date.now(),
      stage: "live-value",
      nodeId: String(node.id || ""),
      dynamic: Boolean(node.dynamicSettingKind),
      rawValue: record.value,
      display: record.display,
      appliedValue: liveValue
    });
    const before = JSON.stringify(
      node.kind === "controller"
        ? settingsPreviewDraft.controllers?.[node.id]
        : node.valueType === "colorX"
          ? {
              value:
                settingsPreviewDraft.values?.[
                  node.id
                ],
              colorState:
                settingsPreviewDraft.colorStates?.[
                  node.id
                ]
            }
          : settingsPreviewDraft.values?.[node.id]
    );
    settingsPreviewApplyRuntimeValue(
      node.id,
      liveValue,
      record
    );
    const after = JSON.stringify(
      node.kind === "controller"
        ? settingsPreviewDraft.controllers?.[node.id]
        : node.valueType === "colorX"
          ? {
              value:
                settingsPreviewDraft.values?.[
                  node.id
                ],
              colorState:
                settingsPreviewDraft.colorStates?.[
                  node.id
                ]
            }
          : settingsPreviewDraft.values?.[node.id]
    );

    if (before !== after) {
      changed = true;
      changedNodeIds.push(String(node.id));
    }
  }

  if (
    settingsPreviewRestoreInactiveLiveValues(
      activeLiveNodeIds
    )
  ) {
    changed = true;
  }

  const receivedNodeIds = [];
  for (const entry of entries) {
    const node = entry?.node;
    if (!node || node.kind === LAYOUT_ROW_KIND || node.valueType === "runtimeDisplay" || node.valueType === "button") {
      continue;
    }
    if (rmlPreviewConfigurationLiveRecord(channel, node.id)) {
      receivedNodeIds.push(String(node.id));
    }
  }

  let runtimePhaseEvaluated = false;
  const uniqueReceivedNodeIds = [...new Set(receivedNodeIds)];
  if (uniqueReceivedNodeIds.length > 0) {
    if (rmlRuntimeDisplayMenuInitializedChannel !== channel) {

      runSettingsPreviewRuntimePhase("startup");
      rmlRuntimeDisplayMenuInitializedChannel = channel;
      runtimePhaseEvaluated = true;
    } else {

      for (const nodeId of [...new Set(changedNodeIds)]) {
        runSettingsPreviewRuntimePhase("saved", nodeId);
        runtimePhaseEvaluated = true;
      }
    }
  }

  return changed || runtimePhaseEvaluated;
}

function rmlRuntimeDisplayEnsurePreviewBridge() {
  const channel =
    window.RMLRuntimeBridge
      ?.projectChannel?.(
        state.metadata.namespaceName,
        state.metadata.className
      ) ||
    `${state.metadata.namespaceName}.${state.metadata.className}`;

  if (
    rmlRuntimeDisplayPreviewUnsubscribe &&
    rmlRuntimeDisplayPreviewChannel ===
      channel
  ) {
    return;
  }

  rmlRuntimeDisplayReleasePreviewBridge();
  rmlRuntimeDisplayPreviewChannel =
    channel;

  const hydratedFromCache =
    rmlRuntimeDisplaySyncConfigurationPreview(channel);
  if (hydratedFromCache) {
    queueMicrotask(() => renderSettingsPreview({ force: true }));
  }

  if (
    window.RMLRuntimeBridge &&
    typeof window.RMLRuntimeBridge
      .subscribe === "function"
  ) {
    try {
      rmlRuntimeDisplayPreviewUnsubscribe =
        window.RMLRuntimeBridge
          .subscribe(
            channel,
            () => {
              const changed =
                rmlRuntimeDisplaySyncConfigurationPreview(channel);
              if (changed) {
                renderSettingsPreview({ force: true });
              }
              rmlRuntimeDisplayRenderPreviewRows();
            }
          );
    } catch {
    }
  }
}

function rmlPreviewVisibleOrderedNodeIds() {
  const flattened =
    typeof flattenNodes === "function"
      ? flattenNodes(state?.nodes || [])
      : [];

  const visibleNodes = flattened
    .filter(entry =>
      entry &&
      entry.node &&
      (
        !Array.isArray(entry.conditions) ||
        entry.conditions.every(condition =>
          settingsPreviewDraft
            ?.controllers?.[
              condition.controller.id
            ] ===
              condition.option.name
        )
      )
    )
    .map(entry => entry.node)
    .filter(node =>
      settingsPreviewNodeVisible(node) &&
      (
        !window.RMLInlineRowLayout
          ?.findContext?.(node?.id)
          ?.row ||
        settingsPreviewNodeVisible(
          window.RMLInlineRowLayout
            ?.findContext?.(node?.id)
            ?.row
        )
      )
    );

  return settingsPreviewOrderedNodes(
    visibleNodes
  )
    .map(node => String(node?.id || ""))
    .filter(Boolean);
}

function rmlPreviewElementNodeId(element) {
  if (!(element instanceof HTMLElement)) {
    return "";
  }

  return String(
    element.dataset?.previewNodeId ||
    element.dataset?.rmlDynamicPreview ||
    element.dataset?.rmlRuntimeDisplayPreview ||
    ""
  );
}

function rmlPreviewInsertByOutlineOrder(
  host,
  element,
  nodeId
) {
  if (
    !(host instanceof HTMLElement) ||
    !(element instanceof HTMLElement)
  ) {
    return;
  }

  const orderedIds =
    rmlPreviewVisibleOrderedNodeIds();

  const currentId =
    String(nodeId || "");

  const currentIndex =
    orderedIds.indexOf(currentId);

  if (currentIndex < 0) {
    host.appendChild(element);
    return;
  }

  const children =
    [...host.children];

  for (
    let index = currentIndex + 1;
    index < orderedIds.length;
    index += 1
  ) {
    const nextId = orderedIds[index];

    const nextElement =
      children.find(candidate =>
        candidate !== element &&
        rmlPreviewElementNodeId(candidate) ===
          nextId
      );

    if (nextElement) {
      host.insertBefore(
        element,
        nextElement
      );
      return;
    }
  }

  host.appendChild(element);
}

function rmlRuntimeDisplayRenderPreviewRows() {
  const dialog =
    document.getElementById(
      "settings-preview-dialog"
    );
  const host =
    document.getElementById(
      "settings-preview-content"
    );

  if (
    !dialog?.open ||
    !host
  ) {
    rmlRuntimeDisplayReleasePreviewBridge();
    return;
  }

  host
    .querySelectorAll(
      "[data-rml-runtime-display-preview]"
    )
    .forEach(element =>
      element.remove()
    );

  if (
    settingsPreviewColorSession ||
    dialog.classList.contains(
      "rml-preview-color-open"
    ) ||
    host.querySelector(
      "[data-preview-color-page]"
    )
  ) {
    return;
  }

  const displays =
    rmlRuntimeDisplayWalk()
      .map(rmlRuntimeDisplayNormalizeNode);

  if (displays.length === 0) {
    rmlRuntimeDisplayReleasePreviewBridge();
    return;
  }

  rmlRuntimeDisplayEnsurePreviewBridge();

  const channel =
    `${state.metadata.namespaceName}.${state.metadata.className}`;

  for (const node of displays) {
    const row =
      window.RMLInlineRowLayout
        ?.findContext?.(node.id)
        ?.row;

    if (
      !settingsPreviewNodeVisible(node) ||
      (
        row &&
        !settingsPreviewNodeVisible(row)
      )
    ) {
      continue;
    }

    const section =
      document.createElement(
        "section"
      );

    section.className =
      "rml-preview-runtime-display";

    window.RMLInlineRowLayout
      ?.applyPreviewLayout?.(
        node,
        section
      );

    section.classList.toggle(
      "label-hidden",
      !settingsPreviewNodeLabelVisible(
        node
      )
    );

    section.dataset
      .rmlRuntimeDisplayPreview =
        node.id;

    section.dataset.previewNodeId =
      String(node.id || "");

    const heading =
      document.createElement(
        "div"
      );

    heading.className =
      "rml-preview-runtime-display-heading";

    const label =
      document.createElement(
        "strong"
      );

    label.textContent =
      node.fieldName ||
      window.RMLI18n.t("ui.auto.74fc53b5138b");

    heading.appendChild(
      label
    );

    const output =
      document.createElement(
        "div"
      );

    output.className =
      "rml-preview-runtime-display-values";

    output.classList.toggle(
      "stacked",
      node.runtimeDisplayStacked === true
    );

    const graphBindings =
      rmlRuntimeDisplayGraphBindings()
        .get(String(node?.id || "")) ||
      [];
    const graphBindingByMonitorId =
      new Map(
        graphBindings
          .filter(binding =>
            String(binding?.monitorId || "")
          )
          .map(binding => [
            String(binding.monitorId),
            binding
          ])
      );
    const configuredMonitorIds =
      Array.isArray(node.runtimeDisplayOrder)
        ? [...new Set(
            node.runtimeDisplayOrder
              .map(value => String(value || ""))
              .filter(Boolean)
          )]
        : [];
    const graph = state.extensions?.typedNodeGraph;
    const graphStructurallyAvailable =
      Array.isArray(graph?.nodes) &&
      Array.isArray(graph?.connections) &&
      graph.nodes.some(candidate =>
        candidate?.kind === "configuration"
      );
    const graphMonitorIds = graphBindings
      .map(binding => String(binding?.monitorId || ""))
      .filter(Boolean);
    const graphMonitorIdSet = new Set(graphMonitorIds);
    const configuredRank = new Map(
      configuredMonitorIds.map((monitorId, index) => [monitorId, index])
    );

    const authoritativeMonitorIds = graphStructurallyAvailable
      ? [...new Set(graphMonitorIds)].sort((left, right) => {
          const lr = configuredRank.has(left)
            ? configuredRank.get(left)
            : Number.MAX_SAFE_INTEGER;
          const rr = configuredRank.has(right)
            ? configuredRank.get(right)
            : Number.MAX_SAFE_INTEGER;
          return lr - rr;
        })
      : configuredMonitorIds;
    const orderedBindings = authoritativeMonitorIds.map(monitorId =>
      graphBindingByMonitorId.get(monitorId) || {
        monitorId,
        label: window.RMLI18n.t("ui.auto.cab95ae29ff4"),
        sequence: Number.MAX_SAFE_INTEGER
      }
    );

    const fallback =
      node.customValidator ||
      window.RMLI18n.t("ui.auto.b1a6ff744a1e");

    const columns =
      orderedBindings.length > 0
        ? orderedBindings.map(binding => {
            const record =
              window.RMLRuntimeBridge
                ?.getValue?.(
                  channel,
                  binding.monitorId
                ) ||
              null;

            return {
              label:
                binding.label ||
                window.RMLI18n.t("ui.auto.cab95ae29ff4"),

              monitorId:
                binding.monitorId,

              items:
                rmlRuntimeDisplayPreviewItems(
                  rmlRuntimeDisplayPreviewText(
                    record,
                    fallback
                  )
                )
            };
          })
        : [
            {
              label:
                window.RMLI18n.t("ui.auto.74fc53b5138b"),

              monitorId:
                "",

              items:
                rmlRuntimeDisplayPreviewItems(
                  fallback
                )
            }
          ];

    const rowCount =
      Math.max(
        1,
        ...columns.map(column =>
          column.items.length
        )
      );

    const runtimeDisplayColumnCount =
      Math.max(1, columns.length);

    output.dataset.rmlRuntimeDisplayColumnCount =
      String(runtimeDisplayColumnCount);
    output.style.setProperty(
      "--rml-runtime-display-column-count",
      String(runtimeDisplayColumnCount)
    );
    section.dataset.rmlRuntimeDisplayColumnCount =
      String(runtimeDisplayColumnCount);

    for (
      let row = 0;
      row < rowCount;
      row += 1
    ) {
      const rowElement =
        document.createElement(
          "div"
        );

      rowElement.className =
        "rml-preview-runtime-display-row";

      for (
        let columnIndex = 0;
        columnIndex < columns.length;
        columnIndex += 1
      ) {
        const column =
          columns[columnIndex];

        const cellValue =
          row < column.items.length
            ? column.items[row]
            : "";

        const cell =
          document.createElement(
            "div"
          );

        cell.className =
          "rml-preview-runtime-display-cell";

        cell.dataset.monitorId =
          column.monitorId;

        const value =
          document.createElement(
            "span"
          );

        value.className =
          "rml-preview-runtime-display-value";

        value.textContent =
          cellValue;

        value.title =
          column.label;

        const copyButton =
          document.createElement(
            "button"
          );

        copyButton.type =
          "button";

        copyButton.className =
          "code-copy-button " +
          "rml-preview-runtime-display-value-copy";

        copyButton.innerHTML =
          rmlRuntimeDisplayPreviewCopyIcon();

        copyButton.setAttribute(
          "aria-label",
          `Copy ${column.label}, item ${row + 1}`
        );

        copyButton.title =
          window.RMLI18n.t("{{i18n:js.presentation.644470b5d763}}");

        copyButton.addEventListener(
          "click",
          () => {
            void copyText(
              cellValue,
              copyButton
            );
          }
        );

        cell.append(
          value,
          copyButton
        );

        rowElement.appendChild(
          cell
        );
      }

      output.appendChild(
        rowElement
      );
    }

    if (
      !settingsPreviewNodeLabelVisible(
        node
      )
    ) {
      section.append(output);
    } else {
      section.append(
        heading,
        output
      );
    }

    const containerId =
      findNodeContainerId(
        state.nodes,
        node.id
      );
    const containerNode =
      containerId
        ? findNode(
            state.nodes,
            containerId
          )
        : null;
    const targetHost =
      containerNode?.kind ===
        LAYOUT_ROW_KIND
        ? host.querySelector(
            `[data-preview-layout-row="${CSS.escape(containerId)}"]`
          ) || host
        : host;

    rmlPreviewInsertByOutlineOrder(
      targetHost,
      section,
      node.id
    );
  }
}

const rmlRuntimeDisplayBasePreviewRenderer =
  renderSettingsPreview;

renderSettingsPreview =
  function (...args) {

    const result =
      rmlRuntimeDisplayBasePreviewRenderer
        .apply(this, args);

    const finish = value => {
      queueMicrotask(
        rmlRuntimeDisplayRenderPreviewRows
      );
      return value;
    };

    return result &&
      typeof result.then === "function"
      ? result.then(finish)
      : finish(result);
  };

